54	  projection.resource_id = resource.id;
55	  projection.station_id = resource.station_id;
56	  projection.available = FacilityResourceAvailable(resource, reservations);
57	  const auto reservation = reservations.find(resource.id);
58	  projection.holder_id = reservation == reservations.end() ? "" : reservation->second.holder_id;
59	  projection.status = FacilityResourceStatus(resource, reservations);
60	  projection.message = "loaded " + resource_label + " state " + resource.id;
61	  return projection;
62	}
