65	  std::vector<std::string> ids;
66	  ids.reserve(reservations.size());
67	  for (const auto& [resource_id, reservation] : reservations) {
68	    (void)reservation;
69	    ids.push_back(resource_id);
70	  }
71	  return ids;
72	}
