74	std::size_t ReleaseResourcesForHolder(
75	    FacilityReservationMap& reservations, const std::string& holder_id) {
76	  std::size_t released = 0U;
77	  for (auto it = reservations.begin(); it != reservations.end();) {
78	    if (it->second.holder_id == holder_id) {
79	      it = reservations.erase(it);
80	      ++released;
81	    } else {
82	      ++it;
83	    }
84	  }
85	  return released;
86	}
