88	FacilityReservationResult ReserveFacilityResource(
89	    FacilityReservationMap& reservations, const FacilityResource& resource,
90	    const std::string& holder_id, const std::string& mission_id,
91	    const bool release_existing_for_holder) {
92	  FacilityReservationResult result;
93	  result.resource_id = resource.id;
94	  result.holder_id = holder_id;
95	
96	  if (!resource.enabled) {
97	    result.status = "disabled";
98	    result.message = "facility resource disabled: " + resource.id;
99	    return result;
100	  }
101	  const auto existing = reservations.find(resource.id);
102	  if (resource.exclusive && existing != reservations.end() &&
103	      existing->second.holder_id != holder_id) {
104	    // A6 先查后放：冲突未通过则直接失败，不得有任何副作用（holder 的既有持有必须保留）
105	    result.holder_id = existing->second.holder_id;
106	    result.status = existing->second.status;
107	    result.message = "facility resource already reserved: " + resource.id;
108	    return result;
109	  }
110	  // 冲突检查全部通过后才释放 holder 的旧持有，避免预约失败连带丢锁
111	  if (release_existing_for_holder) {
112	    ReleaseResourcesForHolder(reservations, holder_id);
113	  }
114	
115	  reservations[resource.id] = ResourceReservation{holder_id, mission_id, "reserved"};
116	  result.success = true;
117	  result.status = "reserved";
118	  result.message = "reserved facility resource " + resource.id + " for " + holder_id;
119	  return result;
120	}
121	
122	FacilityReservationResult ReleaseFacilityResource(
123	    FacilityReservationMap& reservations, const std::string& resource_id,
124	    const std::string& holder_id) {
125	  FacilityReservationResult result;
126	  result.resource_id = resource_id;
127	  const auto existing = reservations.find(resource_id);
128	  if (existing == reservations.end()) {
129	    result.success = true;
130	    result.status = "available";
131	    result.message = "facility resource already available: " + resource_id;
132	    return result;
133	  }
134	  if (!holder_id.empty() && existing->second.holder_id != holder_id) {
135	    result.holder_id = existing->second.holder_id;
136	    result.status = existing->second.status;
137	    result.message = "facility resource held by " + existing->second.holder_id;
138	    return result;
139	  }
140	
141	  reservations.erase(existing);
142	  result.success = true;
143	  result.status = "available";
144	  result.message = "released facility resource " + resource_id;
145	  return result;
146	}
147	
148	bool MarkResourceOccupiedForMission(
149	    FacilityReservationMap& reservations, MissionResourceMap& resource_by_mission,
150	    const std::string& mission_id) {
151	  const auto resource_it = resource_by_mission.find(mission_id);
152	  if (resource_it == resource_by_mission.end()) {
153	    return false;
154	  }
155	  const auto reservation_it = reservations.find(resource_it->second);
156	  if (reservation_it == reservations.end()) {
157	    return false;
158	  }
159	  if (reservation_it->second.hold_after_completion) {
160	    reservation_it->second.status = "occupied";
161	  } else {
162	    reservations.erase(reservation_it);
163	    resource_by_mission.erase(resource_it);
164	  }
165	  return true;
166	}
