168	bool ReleaseResourceForMission(
169	    FacilityReservationMap& reservations, MissionResourceMap& resource_by_mission,
170	    const std::string& mission_id) {
171	  const auto resource_it = resource_by_mission.find(mission_id);
172	  if (resource_it == resource_by_mission.end()) {
173	    return false;
174	  }
175	  const auto reservation_it = reservations.find(resource_it->second);
176	  if (reservation_it != reservations.end() && reservation_it->second.mission_id == mission_id) {
177	    reservations.erase(reservation_it);
178	  }
179	  resource_by_mission.erase(resource_it);
180	  return true;
181	}
