56	BT::NodeStatus FailWithMessage(std::string& message, const std::string& value) {
57	  message = value;
58	  return BT::NodeStatus::FAILURE;
59	}
60	
61	}  // namespace
62	
63	std::string DefaultFacilityActionBehaviorTreeXml() {
64	  return R"(
65	<root BTCPP_format="4" main_tree_to_execute="FacilityActionSubflow">
66	  <BehaviorTree ID="FacilityActionSubflow">
67	    <Sequence>
68	      <SelectFacilityResource/>
69	      <CheckFacilityActionSupported/>
70	      <ReserveFacilityResource/>
71	    </Sequence>
72	  </BehaviorTree>
73	</root>
74	)";
75	}
76	
77	FacilityActionBehaviorTreeResult TickFacilityActionBehaviorTree(
78	    const FacilityActionBehaviorTreeInput& input) {
79	  auto context = MakeFacilityActionContext(input);
80	
81	  BT::BehaviorTreeFactory factory;
82	  factory.registerSimpleAction(
83	      "SelectFacilityResource", [&context](BT::TreeNode&) {
84	        const auto selection = SelectFacilityActionResource(
85	            context.input.catalog, context.result.reservations, context.input.resource_id,
86	            context.input.resource_type);
87	        if (!selection.success || selection.resource == nullptr) {
88	          return FailWithMessage(context.result.message, selection.message);
89	        }
90	        context.selected_resource = selection.resource;
91	        context.result.resource_id = selection.resource->id;
92	        return BT::NodeStatus::SUCCESS;
93	      });
94	  factory.registerSimpleCondition(
95	      "CheckFacilityActionSupported", [&context](BT::TreeNode&) {
96	        if (context.selected_resource == nullptr) {
97	          return FailWithMessage(context.result.message, "facility resource was not selected");
98	        }
99	        if (FacilityActionSupported(context.selected_resource->type, context.input.action)) {
100	          return BT::NodeStatus::SUCCESS;
101	        }
102	        return FailWithMessage(
103	            context.result.message,
104	            "unsupported facility action: " + context.selected_resource->type + "." +
105	                context.input.action);
106	      });
107	  factory.registerSimpleAction(
108	      "ReserveFacilityResource", [&context](BT::TreeNode&) {
109	        if (context.selected_resource == nullptr) {
110	          return FailWithMessage(context.result.message, "facility resource was not selected");
111	        }
112	        context.result.mission_id = BuildFacilityActionMissionId(
113	            context.input.request_id, context.selected_resource->id, context.input.action);
114	        ReserveFacilityActionResource(
115	            context.result.reservations, context.result.resource_by_mission,
116	            *context.selected_resource, context.result.mission_id,
117	            context.input.hold_after_action);
118	        context.result.branch = "facility_action";
119	        context.result.message = "reserved facility resource " + context.selected_resource->id;
120	        return BT::NodeStatus::SUCCESS;
121	      });
122	
123	  auto tree = factory.createTreeFromText(DefaultFacilityActionBehaviorTreeXml());
124	  context.result.success = tree.tickOnce() == BT::NodeStatus::SUCCESS;
125	  return context.result;
126	}
