128	std::string DefaultLiftSessionBehaviorTreeXml() {
129	  return R"(
130	<root BTCPP_format="4" main_tree_to_execute="LiftSessionSubflow">
131	  <BehaviorTree ID="LiftSessionSubflow">
132	    <Fallback>
133	      <Sequence>
134	        <ShouldReleaseLiftSession/>
135	        <ReleaseLiftSession/>
136	      </Sequence>
137	      <Sequence>
138	        <ShouldReserveLiftSession/>
139	        <ReserveLiftSession/>
140	      </Sequence>
141	    </Fallback>
142	  </BehaviorTree>
143	</root>
144	)";
145	}
146	
147	LiftSessionBehaviorTreeResult TickLiftSessionBehaviorTree(
148	    const LiftSessionBehaviorTreeInput& input) {
149	  auto context = MakeLiftSessionContext(input);
150	
151	  BT::BehaviorTreeFactory factory;
152	  factory.registerSimpleCondition(
153	      "ShouldReleaseLiftSession", [&context](BT::TreeNode&) {
154	        return context.input.release ? BT::NodeStatus::SUCCESS : BT::NodeStatus::FAILURE;
155	      });
156	  factory.registerSimpleCondition(
157	      "ShouldReserveLiftSession", [&context](BT::TreeNode&) {
158	        return context.input.release ? BT::NodeStatus::FAILURE : BT::NodeStatus::SUCCESS;
159	      });
160	  factory.registerSimpleAction(
161	      "ReleaseLiftSession", [&context](BT::TreeNode&) {
162	        const auto session_id = BuildLiftSessionId(
163	            context.input.session_id, context.input.lift.id);
164	        context.result.lift_result = ReleaseLiftSessionResource(
165	            context.result.reservations, context.input.lift.id, session_id);
166	        context.result.branch = "lift_release";
167	        return context.result.lift_result.success ? BT::NodeStatus::SUCCESS
168	                                                  : BT::NodeStatus::FAILURE;
169	      });
170	  factory.registerSimpleAction(
171	      "ReserveLiftSession", [&context](BT::TreeNode&) {
172	        const auto session_id = BuildLiftSessionId(
173	            context.input.session_id, context.input.lift.id);
174	        const auto holder_id = BuildLiftSessionHolderId(
175	            context.input.requester_id, session_id);
176	        context.result.lift_result = ReserveLiftSessionResource(
177	            context.result.reservations, context.input.lift, session_id, holder_id,
178	            context.input.release_existing_for_holder);
179	        context.result.branch = "lift_reserve";
180	        return context.result.lift_result.success ? BT::NodeStatus::SUCCESS
181	                                                  : BT::NodeStatus::FAILURE;
182	      });
183	
184	  auto tree = factory.createTreeFromText(DefaultLiftSessionBehaviorTreeXml());
185	  context.result.success = tree.tickOnce() == BT::NodeStatus::SUCCESS;
186	  return context.result;
187	}
