81	DispatcherNode::~DispatcherNode() = default;
82	
83	CallbackReturn DispatcherNode::on_configure(const rclcpp_lifecycle::State& /*state*/) {
84	  const std::size_t cap = get_parameter("queue_capacity").as_int();
85	  const std::string comp_name = get_parameter("comparator").as_string();
86	
87	  queue_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionQueue>(
88	      amr_dispatcher_core::dispatcher::MissionQueue::Config{cap, comp_name});
89	  reservation_table_ = std::make_unique<amr_dispatcher_core::dispatcher::TrafficReservationTable>();
90	  event_log_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionEventLog>(256);
91	  deadlock_detector_ = std::make_unique<amr_dispatcher_core::dispatcher::DeadlockDetector>(
92	      amr_dispatcher_core::dispatcher::DeadlockDetectorConfig{
93	          static_cast<std::size_t>(get_parameter("max_active_missions").as_int()),
94	          10s, 30s});
95	  recovery_policy_ = std::make_unique<amr_dispatcher_core::dispatcher::RecoveryPolicy>();
96	
97	  // 站点目录与基准线性规划器：任务激活时把 pickup→dropoff 展开成 /plan 下发。
98	  // 目录经 StationCatalogReloader 持有：构造时加载，mtime 变化自动热重载；
99	  // 初始加载失败也照常挂监听，文件补齐后下一个 Tick 即生效。
100	  const std::string stations_file = get_parameter("stations_file").as_string();
101	  catalog_reloader_ =
102	      std::make_unique<amr_dispatcher_core::catalog::StationCatalogReloader>(stations_file);
103	  if (catalog_reloader_->loaded()) {
104	    RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s",
105	                catalog_reloader_->catalog().stations.size(), stations_file.c_str());
106	  } else {
107	    RCLCPP_WARN(get_logger(),
108	                "Failed to load stations file %s; planning disabled until hot reload succeeds",
109	                stations_file.c_str());
110	  }
111	  // 依 planner_type 选规划器：skeleton -> 混合图折线循迹，mock -> 直线基线。
112	  // catalog_reloader_ 已就位（即使初始加载失败也持有空目录，热重载后由 reload_timer_ 同步）。
113	  RebuildPlanner();
114	
115	  // ---- 批次 2：调度状态恢复（state_snapshot_file 为空 = 关闭）----
116	  state_snapshot_file_ = get_parameter("state_snapshot_file").as_string();
117	  state_snapshot_debounce_sec_ = get_parameter("state_snapshot_debounce_sec").as_double();
118	  audit_log_file_ = get_parameter("audit_log_file").as_string();
119	  if (!state_snapshot_file_.empty()) {
120	    std::string reason;
121	    const auto restored = amr_dispatcher_core::dispatcher::LoadDispatchState(
122	        state_snapshot_file_, &reason);
123	    if (!restored.has_value()) {
124	      if (reason == "not_found") {
125	        RCLCPP_INFO(get_logger(), "No dispatch state snapshot at %s (fresh start)",
126	                    state_snapshot_file_.c_str());
127	      } else {
128	        // 坏快照绝不"尽力而为"：拒绝恢复并保留现场，人工判断后再清理
129	        RCLCPP_ERROR(get_logger(),
130	                     "Refusing to restore dispatch state from %s: %s (starting fresh; "
131	                     "the file is left untouched for inspection)",
132	                     state_snapshot_file_.c_str(), reason.c_str());
133	      }
134	    } else {
135	      // 地图版本门禁：拿旧拓扑的队列去派发 = 派到不存在的站点
136	      const std::string current_map_hash =
137	          catalog_reloader_ ? catalog_reloader_->catalog().map_hash : std::string();
138	      if (!restored->map_hash.empty() && !current_map_hash.empty() &&
139	          restored->map_hash != current_map_hash) {
140	        RCLCPP_ERROR(get_logger(),
141	                     "Refusing to restore dispatch state: snapshot map_hash=%s does not match "
142	                     "current map_hash=%s (topology changed); starting with an empty queue",
143	                     restored->map_hash.c_str(), current_map_hash.c_str());
144	        AppendAudit("restore_state_rejected", "", "", "system",
145	                    "map_hash mismatch: snapshot=" + restored->map_hash +
146	                        " current=" + current_map_hash);
147	      } else {
148	        std::vector<amr_dispatcher_core::dispatcher::Mission> queued = restored->queued_missions;
149	        // 暂停订单下的任务先移出队列：它们在暂停期间本就不可派发，
150	        // 先入队再标暂停会被容量上限挤掉（等于丢单），所以恢复完暂停标记再补回。
151	        std::vector<amr_dispatcher_core::dispatcher::Mission> paused_backlog;
152	        std::unordered_set<std::string> paused_orders(restored->paused_order_ids.begin(),
153	                                                      restored->paused_order_ids.end());
154	        for (const auto& m : queued) {
155	          if (!m.order_id.empty() && paused_orders.count(m.order_id) > 0) {
156	            paused_backlog.push_back(m);  // 暂停期间本就不可派发：稍后补回
157	          }
158	        }
159	        queued.erase(std::remove_if(queued.begin(), queued.end(),
160	                                    [&paused_orders](const auto& m) {
161	                                      return !m.order_id.empty() &&
162	                                             paused_orders.count(m.order_id) > 0;
163	                                    }),
164	                     queued.end());
165	        // 重启时仍在执行的任务：新进程没有任何车辆在跑它们，重新入队而不是假装在途
166	        for (const auto& m : restored->active_missions) {
167	          amr_dispatcher_core::dispatcher::Mission requeued = m;
168	          requeued.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
169	          requeued.result = amr_dispatcher_core::dispatcher::MissionResult::kNone;
170	          requeued.reservation_id.clear();  // 旧锁属于已死亡的进程
171	          if (!requeued.order_id.empty() && paused_orders.count(requeued.order_id) > 0) {
172	            paused_backlog.push_back(std::move(requeued));
173	          } else {
174	            queued.push_back(std::move(requeued));
175	          }
176	        }
177	        std::size_t restored_count = queue_->Restore(queued, restored->paused_order_ids);
178	        if (!paused_backlog.empty()) {
179	          // 暂停标记已在 Restore 里生效，现在把它们补回队列（不受"可派"语义影响）
180	          restored_count += queue_->RestoreAppend(paused_backlog);
181	        }
182	        next_sequence_ = restored->next_sequence;
183	        // 隔离态必须等 SetupVda5050Links 之后再灌：它会先 clear() 旧链路态，
184	        // 此处直接写入会被随后的 clear 抹掉。
185	        restored_quarantined_ = restored->quarantined_vehicle_ids;
186	        RCLCPP_INFO(get_logger(),
187	                    "Restored dispatch state from %s: %zu queued (%zu re-queued from active), "
188	                    "%zu paused order(s), %zu quarantined vehicle(s), next_sequence=%llu",
189	                    state_snapshot_file_.c_str(), restored_count,
190	                    restored->active_missions.size(), restored->paused_order_ids.size(),
191	                    restored->quarantined_vehicle_ids.size(),
192	                    static_cast<unsigned long long>(next_sequence_));
193	        if (restored_count < queued.size()) {
194	          RCLCPP_WARN(get_logger(),
195	                      "Snapshot contained %zu mission(s) that could not be restored "
196	                      "(duplicate ids, empty ids, or over queue capacity)",
197	                      queued.size() - restored_count);
198	        }
199	        AppendAudit("restore_state", "", "", "system",
200	                    "restored " + std::to_string(restored_count) + " queued mission(s)");
201	      }
202	    }
203	  }
204	
205	  state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::DispatcherState>(
206	      "/dispatcher/state", 10);
207	  event_pub_ = create_publisher<amr_dispatcher_interfaces::msg::MissionEvent>(
208	      "/dispatcher/events", 20);
209	  plan_pub_ = create_publisher<nav_msgs::msg::Path>("/plan", 1);
210	  // 拓扑状态：safety_gate（deadlock_active_）与 visualizer（绿锁边/红警戒柱）的死锁输入
211	  topology_pub_ = create_publisher<amr_dispatcher_interfaces::msg::TopologyState>(
212	      "/dispatcher/topology_state", 10);
213	
214	  // 位姿与到达信号订阅：path_tracker 的 TrackingError.arrived 驱动任务完成
215	  odom_sub_ = create_subscription<nav_msgs::msg::Odometry>(
216	      "/odom", 10, std::bind(&DispatcherNode::OdomCb, this, std::placeholders::_1));
217	  tracking_error_sub_ = create_subscription<amr_dispatcher_interfaces::msg::TrackingError>(
218	      "/tracking/error", 10,
219	      std::bind(&DispatcherNode::TrackingErrorCb, this, std::placeholders::_1));
220	
221	  // Task 5：VDA 5050 状态/链路接入（逐段解锁 + 断链守卫），按参数建订阅
222	  SetupVda5050Links(get_parameter("vda5050_vehicles").as_string());
223	  // 批次 2：把快照里的隔离车辆重新置为隔离（SetupVda5050Links 已先清空链路态表）
224	  for (const auto& vid : restored_quarantined_) {
