240	  traffic_mode_ = get_parameter("traffic_mode").as_string();
241	  if (traffic_mode_ != "static" && traffic_mode_ != "time_space") {
242	    RCLCPP_ERROR(get_logger(),
243	                 "Invalid traffic_mode '%s' — falling back to 'static' (unknown mode is not "
244	                 "guessed)",
245	                 traffic_mode_.c_str());
246	    traffic_mode_ = "static";
247	  }
