254	  time_space_timing_.min_headway_sec = get_parameter("time_space_min_headway_sec").as_double();
255	  RCLCPP_INFO(get_logger(), "Traffic coordination mode: %s", traffic_mode_.c_str());
256	
257	  // P0.6 / A6：选车上下文（静态目录 + 参数）
258	  required_capability_ = get_parameter("required_capability").as_string();
259	  min_battery_percent_ = get_parameter("min_battery_percent").as_double();
260	  {
261	    const std::string label = get_parameter("vehicle_selection_strategy").as_string();
262	    if (!amr_dispatcher_core::fleet::ParseVehicleSelectionStrategy(
263	            label, &vehicle_selection_strategy_)) {
264	      RCLCPP_WARN(get_logger(),
265	                  "Invalid vehicle_selection_strategy '%s' — falling back to 'nearest' "
266	                  "(unknown strategies are never guessed)",
267	                  label.c_str());
268	      vehicle_selection_strategy_ = amr_dispatcher_core::fleet::VehicleSelectionStrategy::kNearest;
269	    }
270	    RCLCPP_INFO(get_logger(), "Vehicle selection strategy: %s",
271	                amr_dispatcher_core::fleet::VehicleSelectionStrategyLabel(
272	                    vehicle_selection_strategy_));
273	  }
274	  vehicle_state_max_age_ms_ = get_parameter("vehicle_state_max_age_ms").as_int();
275	  LoadFleetCatalog();
276	
277	  submit_srv_ = create_service<amr_dispatcher_interfaces::srv::SubmitOrder>(
278	      "/dispatcher/submit_order",
279	      std::bind(&DispatcherNode::SubmitOrderCb, this, std::placeholders::_1, std::placeholders::_2));
280	  cancel_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelOrder>(
281	      "/dispatcher/cancel_order",
282	      std::bind(&DispatcherNode::CancelOrderCb, this, std::placeholders::_1, std::placeholders::_2));
283	  pause_srv_ = create_service<amr_dispatcher_interfaces::srv::PauseMission>(
284	      "/dispatcher/pause_mission",
285	      std::bind(&DispatcherNode::PauseMissionCb, this, std::placeholders::_1, std::placeholders::_2));
286	  resume_srv_ = create_service<amr_dispatcher_interfaces::srv::ResumeMission>(
287	      "/dispatcher/resume_mission",
288	      std::bind(&DispatcherNode::ResumeMissionCb, this, std::placeholders::_1, std::placeholders::_2));
289	  reserve_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveResource>(
290	      "/dispatcher/reserve_resource",
291	      std::bind(&DispatcherNode::ReserveResourceCb, this, std::placeholders::_1, std::placeholders::_2));
292	  release_srv_ = create_service<amr_dispatcher_interfaces::srv::ReleaseResource>(
293	      "/dispatcher/release_resource",
294	      std::bind(&DispatcherNode::ReleaseResourceCb, this, std::placeholders::_1, std::placeholders::_2));
295	  force_clear_vda5050_link_srv_ =
296	      create_service<amr_dispatcher_interfaces::srv::ForceClearVda5050Link>(
297	          "/dispatcher/force_clear_vda5050_link",
298	          std::bind(&DispatcherNode::ForceClearVda5050LinkCb, this,
299	                    std::placeholders::_1, std::placeholders::_2));
300	  restore_vda5050_link_srv_ =
301	      create_service<amr_dispatcher_interfaces::srv::RestoreVda5050Link>(
302	          "/dispatcher/restore_vda5050_link",
303	          std::bind(&DispatcherNode::RestoreVda5050LinkCb, this,
304	                    std::placeholders::_1, std::placeholders::_2));
305	
306	  // 12 Core Services Registration
307	  enqueue_srv_ = create_service<amr_dispatcher_interfaces::srv::EnqueueMission>(
308	      "/v2/enqueue_mission",
309	      std::bind(&DispatcherNode::EnqueueMissionCb, this, std::placeholders::_1, std::placeholders::_2));
310	  cancel_queued_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelQueuedMission>(
311	      "/v2/cancel_queued_mission",
312	      std::bind(&DispatcherNode::CancelQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
313	  preempt_srv_ = create_service<amr_dispatcher_interfaces::srv::PreemptMission>(
314	      "/v2/preempt_mission",
315	      std::bind(&DispatcherNode::PreemptMissionCb, this, std::placeholders::_1, std::placeholders::_2));
316	  reprioritize_srv_ = create_service<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission>(
317	      "/v2/reprioritize_queued_mission",
318	      std::bind(&DispatcherNode::ReprioritizeQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
319	  estimate_cost_srv_ = create_service<amr_dispatcher_interfaces::srv::EstimateMissionCost>(
320	      "/v2/estimate_mission_cost",
321	      std::bind(&DispatcherNode::EstimateMissionCostCb, this, std::placeholders::_1, std::placeholders::_2));
322	  block_route_srv_ = create_service<amr_dispatcher_interfaces::srv::BlockStationRoute>(
323	      "/v2/block_station_route",
324	      std::bind(&DispatcherNode::BlockStationRouteCb, this, std::placeholders::_1, std::placeholders::_2));
325	  detect_deadlock_srv_ = create_service<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock>(
326	      "/v2/detect_traffic_deadlock",
327	      std::bind(&DispatcherNode::DetectTrafficDeadlockCb, this, std::placeholders::_1, std::placeholders::_2));
328	  list_stations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListStations>(
329	      "/v2/list_stations",
330	      std::bind(&DispatcherNode::ListStationsCb, this, std::placeholders::_1, std::placeholders::_2));
331	  list_reservations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListTrafficReservations>(
332	      "/v2/list_traffic_reservations",
333	      std::bind(&DispatcherNode::ListTrafficReservationsCb, this, std::placeholders::_1, std::placeholders::_2));
334	  reserve_facility_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveFacilityResource>(
335	      "/v2/reserve_facility_resource",
336	      std::bind(&DispatcherNode::ReserveFacilityResourceCb, this, std::placeholders::_1, std::placeholders::_2));
337	  snapshot_srv_ = create_service<amr_dispatcher_interfaces::srv::GetOperatorSnapshot>(
338	      "/v2/get_operator_snapshot",
339	      std::bind(&DispatcherNode::GetOperatorSnapshotCb, this, std::placeholders::_1, std::placeholders::_2));
340	  validate_site_srv_ = create_service<amr_dispatcher_interfaces::srv::ValidateSiteConfig>(
341	      "/v2/validate_site_config",
342	      std::bind(&DispatcherNode::ValidateSiteConfigCb, this, std::placeholders::_1, std::placeholders::_2));
343	
344	  // 导航后端：默认 plan（行为与既有代码逐字节一致）；action 模式派发改发 NavigateSequence 单点 goal
345	  navigation_backend_ = get_parameter("navigation_backend").as_string();
346	  if (navigation_backend_ != "plan" && navigation_backend_ != "action") {
347	    RCLCPP_WARN(get_logger(), "Unknown navigation_backend '%s', falling back to 'plan'",
348	                navigation_backend_.c_str());
349	    navigation_backend_ = "plan";
350	  }
351	  // ExecuteMission action server：HandleGoal 校验（非空/不重复/资源可预占），
352	  // HandleAccepted 只做入队 + 存 goal handle（不起线程）
353	  execute_action_server_ = rclcpp_action::create_server<ExecuteMission>(
354	      this, "/execute_mission",
355	      std::bind(&DispatcherNode::HandleGoal, this, std::placeholders::_1, std::placeholders::_2),
356	      std::bind(&DispatcherNode::HandleCancel, this, std::placeholders::_1),
357	      std::bind(&DispatcherNode::HandleAccepted, this, std::placeholders::_1));
358	  if (navigation_backend_ == "action") {
359	    nav_client_ = rclcpp_action::create_client<NavigateSequence>(this, "/navigate_sequence");
360	  }
361	
362	  // B6：参数热重载——比较器与三个调度节奏参数允许运行时改写。
363	  // 校验失败返回空 reason（rclcpp 按"拒绝"处理）；comparator 在此预校验，
364	  // 未知值直接拒绝（避免 SetComparator 对未知名静默失败导致实际策略与参数漂移）。
365	  param_callback_handle_ = add_on_set_parameters_callback(
366	      [this](const std::vector<rclcpp::Parameter>& params) {
367	        rcl_interfaces::msg::SetParametersResult result;
368	        result.successful = true;
369	        for (const auto& p : params) {
370	          const std::string& name = p.get_name();
371	          if (name == "comparator") {
372	            const std::string v = p.as_string();
373	            auto comp = amr_dispatcher_core::dispatcher::CreateMissionComparator(v);
374	            if (!comp) {
375	              result.successful = false;
376	              result.reason = "unknown comparator: " + v;
377	              RCLCPP_WARN(get_logger(), "Parameter reload rejected: %s",
378	                          result.reason.c_str());
379	              continue;
380	            }
381	            if (queue_) {
382	              queue_->SetComparator(std::move(comp));
383	            }
384	            RCLCPP_INFO(get_logger(), "Parameter reload: comparator -> %s", v.c_str());
385	          } else if (name == "schedule_rate_hz") {
386	            const double v = p.as_double();
387	            if (v <= 0.0) {
388	              result.successful = false;
389	              result.reason = "schedule_rate_hz must be > 0";
390	              continue;
391	            }
392	            if (schedule_timer_) {
393	              schedule_timer_->reset();
394	              schedule_timer_ = create_wall_timer(
395	                  std::chrono::duration<double>(1.0 / v),
396	                  std::bind(&DispatcherNode::ScheduleTick, this));
397	            }
398	            RCLCPP_INFO(get_logger(), "Parameter reload: schedule_rate_hz -> %.2f", v);
399	          } else if (name == "deadlock_check_rate_hz") {
400	            const double v = p.as_double();
401	            if (v <= 0.0) {
402	              result.successful = false;
403	              result.reason = "deadlock_check_rate_hz must be > 0";
404	              continue;
405	            }
406	            if (deadlock_timer_) {
407	              deadlock_timer_->reset();
408	              deadlock_timer_ = create_wall_timer(
409	                  std::chrono::duration<double>(1.0 / v),
410	                  std::bind(&DispatcherNode::DeadlockTick, this));
411	            }
412	            RCLCPP_INFO(get_logger(), "Parameter reload: deadlock_check_rate_hz -> %.2f", v);
413	          } else if (name == "max_active_missions") {
414	            const int64_t v = p.as_int();
415	            if (v < 1) {
416	              result.successful = false;
417	              result.reason = "max_active_missions must be >= 1";
418	              continue;
419	            }
420	            RCLCPP_INFO(get_logger(), "Parameter reload: max_active_missions -> %lld",
421	                        static_cast<long long>(v));
422	          } else if (name == "planner_type") {
423	            const std::string v = p.as_string();
424	            if (v != "mock" && v != "skeleton") {
425	              result.successful = false;
426	              result.reason = "planner_type must be 'mock' or 'skeleton': " + v;
427	              RCLCPP_WARN(get_logger(), "Parameter reload rejected: %s",
428	                          result.reason.c_str());
429	              continue;
430	            }
431	            planner_type_ = v;
432	            RebuildPlanner();  // 单线程 spin：回调期间无规划请求在途，可安全换实例
433	            RCLCPP_INFO(get_logger(), "Parameter reload: planner_type -> %s", v.c_str());
434	          } else if (name == "expected_map_hash") {
435	            expected_map_hash_ = p.as_string();
436	            RCLCPP_INFO(get_logger(),
437	                        "Parameter reload: expected_map_hash -> %s",
438	                        expected_map_hash_.empty() ? "<disabled>"
439	                                                   : expected_map_hash_.c_str());
440	          }
441	          // 其余已声明参数不回执：rclcpp 仍正常赋值，仅不产生日志噪声
442	        }
443	        return result;
444	      });
445	
446	  RCLCPP_INFO(get_logger(),
447	              "DispatcherNode configured (capacity=%zu, comparator=%s, navigation_backend=%s)",
448	              cap, comp_name.c_str(), navigation_backend_.c_str());
449	  return CallbackReturn::SUCCESS;
450	}
