452	CallbackReturn DispatcherNode::on_activate(const rclcpp_lifecycle::State& /*state*/) {
453	  state_pub_->on_activate();
454	  event_pub_->on_activate();
455	  plan_pub_->on_activate();
456	  topology_pub_->on_activate();
457	  for (auto& [vehicle_id, pub] : vda5050_order_pubs_) {
458	    pub->on_activate();  // Task 6：send_order 发布端随节点激活（未激活则 publish 为空操作）
459	  }
460	  for (auto& [vehicle_id, pub] : vehicle_plan_pubs_) {
461	    pub->on_activate();  // P0.6：per-vehicle 计划发布端随节点激活
462	  }
463	
464	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
465	  schedule_timer_ = create_wall_timer(
466	      std::chrono::duration<double>(1.0 / sched_hz),
467	      std::bind(&DispatcherNode::ScheduleTick, this));
468	
469	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
470	  deadlock_timer_ = create_wall_timer(
471	      std::chrono::duration<double>(1.0 / deadlock_hz),
472	      std::bind(&DispatcherNode::DeadlockTick, this));
473	
474	  state_timer_ = create_wall_timer(500ms, std::bind(&DispatcherNode::PublishState, this));
475	
476	  // 1Hz 驱动站点目录 mtime 热重载（HotReloadWatcher 由调用方驱动）
477	  reload_timer_ = create_wall_timer(1s, [this]() {
478	    if (!catalog_reloader_) return;
479	    if (catalog_reloader_->Tick()) {
480	      RCLCPP_INFO(get_logger(), "Station catalog hot-reloaded: %zu stations",
481	                  catalog_reloader_->catalog().stations.size());
482	      // SkeletonPlanner 持有目录副本：热重载后必须同步，否则仍按旧折线规划
483	      auto* skeleton_planner =
484	          dynamic_cast<amr_dispatcher_core::planning::SkeletonPlanner*>(planner_.get());
485	      if (skeleton_planner != nullptr) {
486	        skeleton_planner->UpdateCatalog(catalog_reloader_->catalog());
487	        RCLCPP_INFO(get_logger(), "SkeletonPlanner catalog synchronized (%zu stations)",
488	                    catalog_reloader_->catalog().stations.size());
489	      }
490	    } else if (!catalog_reloader_->last_error().empty()) {
491	      // 重载失败（YAML 解析或校验不过）：旧目录继续生效，节流告警提示修复文件
492	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
493	                           "Station catalog reload failed, keeping previous: %s",
494	                           catalog_reloader_->last_error().c_str());
495	    }
496	  });
497	
498	  RCLCPP_INFO(get_logger(), "DispatcherNode activated");
499	  return CallbackReturn::SUCCESS;
500	}
