502	void DispatcherNode::RebuildPlanner() {
503	  const double step_size = get_parameter("path_step_size_m").as_double();
504	  if (planner_type_ == "skeleton") {
505	    planner_ = std::make_unique<amr_dispatcher_core::planning::SkeletonPlanner>(
506	        catalog_reloader_ ? catalog_reloader_->catalog()
507	                          : amr_dispatcher_core::catalog::StationCatalog{},
508	        amr_dispatcher_core::planning::SkeletonPlanner::Config{step_size});
509	    RCLCPP_INFO(get_logger(),
510	                "Path planner: SkeletonPlanner (mixed-graph polyline, step %.2f m)",
511	                step_size);
512	    return;
513	  }
514	  if (planner_type_ != "mock") {
515	    RCLCPP_WARN(get_logger(),
516	                "Unknown planner_type '%s', falling back to MockLinearPlanner",
517	                planner_type_.c_str());
518	  }
519	  planner_ = std::make_unique<amr_dispatcher_core::MockLinearPlanner>(step_size);
520	  RCLCPP_INFO(get_logger(), "Path planner: MockLinearPlanner (step %.2f m)", step_size);
521	}
