523	CallbackReturn DispatcherNode::on_deactivate(const rclcpp_lifecycle::State& /*state*/) {
524	  // 批次 2：停 tick 之前强制落盘，避免最后一次变更停在内存里
525	  FlushStateSnapshot();
526	  schedule_timer_.reset();
527	  deadlock_timer_.reset();
528	  state_timer_.reset();
529	  reload_timer_.reset();
530	  state_pub_->on_deactivate();
531	  event_pub_->on_deactivate();
532	  plan_pub_->on_deactivate();
533	  topology_pub_->on_deactivate();
534	  for (auto& [vehicle_id, pub] : vda5050_order_pubs_) {
535	    pub->on_deactivate();
536	  }
537	  for (auto& [vehicle_id, pub] : vehicle_plan_pubs_) {
538	    pub->on_deactivate();
539	  }
540	  RCLCPP_INFO(get_logger(), "DispatcherNode deactivated");
541	  return CallbackReturn::SUCCESS;
542	}
