544	CallbackReturn DispatcherNode::on_cleanup(const rclcpp_lifecycle::State& /*state*/) {
545	  submit_srv_.reset();
546	  cancel_srv_.reset();
547	  pause_srv_.reset();
548	  resume_srv_.reset();
549	  reserve_srv_.reset();
550	  release_srv_.reset();
551	  force_clear_vda5050_link_srv_.reset();
552	  restore_vda5050_link_srv_.reset();
553	  enqueue_srv_.reset();
554	  cancel_queued_srv_.reset();
555	  preempt_srv_.reset();
556	  reprioritize_srv_.reset();
557	  estimate_cost_srv_.reset();
558	  block_route_srv_.reset();
559	  detect_deadlock_srv_.reset();
560	  list_stations_srv_.reset();
561	  list_reservations_srv_.reset();
562	  reserve_facility_srv_.reset();
563	  snapshot_srv_.reset();
564	  validate_site_srv_.reset();
565	  // B2：clean up 前先逐个收口在途 ExecuteMission goal——
566	  // 不复位的 handle 在 server 销毁后会让 action 客户端永久悬挂；
567	  // 同时释放 HandleGoal 阶段预占的 required_resources 锁。
568	  // rclcpp_action 状态机约束：canceled() 仅 CANCELING、abort() 仅 EXECUTING，
569	  // 其余状态（ACCEPTED 未执行）先 execute() 再 abort()，与 FinishExecuteGoal 同构。
570	  for (auto& [mission_id, handle] : execute_goal_handles_) {
571	    if (!handle) {
572	      continue;
573	    }
574	    if (reservation_table_) {
575	      reservation_table_->Release(mission_id);
576	    }
577	    auto result = std::make_shared<ExecuteMission::Result>();
578	    result->success = false;
579	    result->error_code = 1;
580	    result->message = "dispatcher cleaning up";
581	    try {
582	      if (handle->is_canceling()) {
583	        handle->canceled(result);
584	      } else if (handle->is_executing()) {
585	        handle->abort(result);
586	      } else {
587	        handle->execute();
588	        handle->abort(result);
589	      }
590	    } catch (const std::exception& ex) {
591	      RCLCPP_ERROR(get_logger(), "on_cleanup: finish goal %s failed: %s",
592	                   mission_id.c_str(), ex.what());
593	    }
594	  }
595	  execute_action_server_.reset();
596	  nav_client_.reset();
597	  execute_goal_handles_.clear();
598	  mission_dispatch_start_.clear();
599	  mission_dispatch_time_.clear();
600	  pending_wait_.clear();
601	  mission_reserved_at_.clear();
602	  pending_nav_mission_id_.clear();
603	  pending_nav_goal_handle_.reset();
604	  state_pub_.reset();
605	  event_pub_.reset();
606	  plan_pub_.reset();
607	  topology_pub_.reset();
608	  vda5050_order_pubs_.clear();   // Task 6：随生命周期收口，重 configure 时重建
609	  vda5050_vehicle_ids_.clear();
610	  vda5050_link_subs_.clear();    // 终审 M4：与 SetupVda5050Links 开头清旧对齐，防残留链
611	  vda5050_link_states_.clear();
612	  vda5050_next_order_update_id_.clear();
613	  vda5050_mission_vehicle_.clear();  // Task 7：mission->车辆绑定随生命周期收口
614	  // 隔离态随生命周期收口（隔离位存在链路态表里，上方的 clear 已经清掉）
615	  // P0.6：per-vehicle 资源随生命周期收口，重 configure 时重建
616	  vehicle_plan_pubs_.clear();
617	  vehicle_odom_subs_.clear();
618	  vehicle_tracking_error_subs_.clear();
619	  vehicle_poses_.clear();
620	  vehicle_ids_.clear();
621	  last_deadlock_findings_.clear();
622	  tracking_error_sub_.reset();
623	  odom_sub_.reset();
624	  queue_.reset();
625	  reservation_table_.reset();
626	  // 批次 2：持久化通道随生命周期收口（快照文件本身保留，供下次启动恢复）
627	  state_snapshot_dirty_ = false;
628	  last_state_snapshot_error_.clear();
629	  event_log_.reset();
630	  deadlock_detector_.reset();
631	  recovery_policy_.reset();
632	  planner_.reset();
633	  catalog_reloader_.reset();
634	  reload_timer_.reset();
635	  // 批次 2：持久化开关随生命周期收口（配置在下一次 configure 重新读取）。
636	  // 手动生命周期切换（deactivate -> cleanup -> configure）不应把上一次的
637	  // 队列当成"重启恢复"再灌一遍。
638	  state_snapshot_file_.clear();
639	  audit_log_file_.clear();
640	  restored_quarantined_.clear();
641	  queue_start_requested_ = false;
642	  vehicle_current_mission_.clear();
643	  mission_tracking_vehicle_.clear();
644	  vehicle_states_.clear();
645	  auto_assignment_paused_ = false;
646	  time_space_occupancy_ = amr_dispatcher_core::workflow::TimeSpaceOccupancy{};
647	  time_space_windows_.clear();
648	  active_missions_.clear();
649	  return CallbackReturn::SUCCESS;
650	}
