658	void DispatcherNode::SubmitOrderCb(
659	    const std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Request> req,
660	    std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Response> resp) {
661	  if (!queue_) {
662	    resp->accepted = false;
663	    resp->message = "Dispatcher not configured";
664	    return;
665	  }
666	
667	  // 订单路由：经 submit_order 行为树调用路由器，决定订单类型语义与字段回填。
668	  // 未知/空类型由路由器统一拒绝（message 带 supported 列表）。
669	  amr_dispatcher_bt::SubmitOrderBehaviorTreeInput route_input;
670	  route_input.request.order_id = req->order_id.empty() ? req->mission_id : req->order_id;
671	  route_input.request.order_type = req->mission_type.empty() ? "transport" : req->mission_type;
672	  route_input.request.priority = req->priority;
673	  const auto route_result = amr_dispatcher_bt::TickSubmitOrderBehaviorTree(route_input);
674	  if (!route_result.success || !route_result.route) {
675	    resp->accepted = false;
676	    resp->mission_id = req->mission_id;
677	    resp->message = "route rejected: " + route_result.message;
678	    RCLCPP_WARN(get_logger(), "SubmitOrder rejected by router: %s", resp->message.c_str());
679	    return;
680	  }
681	  const auto& route = *route_result.route;
682	
683	  amr_dispatcher_core::dispatcher::Mission m;
684	  // B4：id/sequence 同源——自动 id 用戳记器保证 "m_<n>" 与 sequence=n 一致；
685	  // 调用方显式给 id 时仍消费一次序列号，保持全局单调。
686	  if (req->mission_id.empty()) {
687	    StampMissionIdentity(m, next_sequence_);
688	  } else {
689	    m.id = req->mission_id;
690	    m.sequence = next_sequence_++;
691	  }
692	  m.order_id = req->order_id.empty() ? ("ord_" + m.id) : req->order_id;
693	  m.type = route.normalized_order_type.empty() ? "transport" : route.normalized_order_type;
694	  // 站点字段优先取请求显式值，路由器解析出的站点作兜底
695	  m.pickup_station = req->pickup_station.empty() ? route.pickup_station : req->pickup_station;
696	  m.dropoff_station = req->dropoff_station.empty() ? route.dropoff_station : req->dropoff_station;
697	  m.priority = req->priority;
698	  m.deadline_unix_ms = req->deadline_unix_ms;
699	  m.expected_seconds = req->expected_seconds;
700	  // 显式指定承接车辆（空 = 由选车策略决定，见 core/fleet/vehicle_assignment.hpp）
701	  m.assigned_vehicle_id = req->assigned_vehicle_id;
702	
703	  auto res = queue_->Push(m);
704	  resp->accepted = res.accepted;
705	  resp->mission_id = m.id;
706	  resp->message = res.message;
707	  if (res.accepted) {
708	    MarkStateDirty();
709	    if (route.start_if_idle) {
710	      queue_start_requested_ = true;
711	    }
712	    RCLCPP_INFO(get_logger(),
713	                "SubmitOrder routed via BT: branch=%s kind=%d type=%s start_if_idle=%d",
714	                route_result.branch.c_str(), static_cast<int>(route.kind), m.type.c_str(),
715	                route.start_if_idle ? 1 : 0);
716	    amr_dispatcher_core::dispatcher::MissionEvent evt;
717	    evt.stamp = "now";
718	    evt.mission_id = m.id;
719	    evt.event = "queued";
720	    event_log_->Append(evt);
721	
722	    if (event_pub_ && event_pub_->is_activated()) {
723	      amr_dispatcher_interfaces::msg::MissionEvent msg;
724	      msg.stamp = now();
725	      msg.mission_id = m.id;
726	      msg.order_id = m.order_id;
727	      msg.event = "queued";
728	      msg.to_state = "PENDING";
729	      msg.reason = "submitted";
730	      event_pub_->publish(msg);
731	    }
732	  }
733	}
