735	void DispatcherNode::CancelOrderCb(
736	    const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Request> req,
737	    std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Response> resp) {
738	  if (!queue_) {
739	    resp->success = false;
740	    resp->message = "Dispatcher not active";
741	    return;
742	  }
743	  if (!req->mission_id.empty()) {
744	    bool ok = queue_->Cancel(req->mission_id);
745	    if (ok) {
746	      MarkStateDirty();
747	    }
748	    if (ok) {
749	      // action 提交的任务在排队中被取消：helper 终结 handle + 释放 HandleGoal 预占
750	      CleanupMissionCancel(req->mission_id, "mission canceled by operator");
751	      resp->success = true;
752	      resp->canceled_count = 1;
753	      resp->message = "Mission canceled from queue";
754	    } else {
755	      auto it = active_missions_.find(req->mission_id);
756	      if (it != active_missions_.end()) {
757	        // 释放资源锁；若该任务正在占用 /plan，发空路径停车
758	        if (reservation_table_) {
759	          reservation_table_->Release(req->mission_id);
760	        }
761	        if (IsMissionTracked(req->mission_id)) {
762	          ReleaseTrackingSlot(req->mission_id);
763	          PublishStopPathForMission(req->mission_id);
764	        }
765	        active_missions_.erase(it);
766	        MarkStateDirty();
767	        // helper：终结 ExecuteMission goal（未受理 action cancel → 降级 abort(3)）
768	        // 并级联取消在途 NavigateSequence goal（清 pending_nav_*）
769	        CleanupMissionCancel(req->mission_id, "mission canceled by operator");
770	        resp->success = true;
771	        resp->canceled_count = 1;
772	        resp->message = "Active mission canceled";
773	      } else {
774	        resp->success = false;
775	        resp->canceled_count = 0;
776	        resp->message = "Mission not found";
777	      }
778	    }
779	    ReArmQueueStartRequest();  // 取消活动任务后，队列后续任务需重新武装启动请求
780	    return;
781	  }
782	  if (!req->order_id.empty()) {
783	    // 整单批量取消：取消前对在队任务取证（仅存在 action handle 时取证，plan 模式零开销），
784	    // 取消成功后逐个收口 handle/预占/pending_nav（审查 I5）
785	    std::vector<std::string> action_mission_ids;
786	    if (!execute_goal_handles_.empty()) {
787	      for (const auto& qm : queue_->Snapshot()) {
788	        if (qm.order_id == req->order_id) {
789	          action_mission_ids.push_back(qm.id);
790	        }
791	      }
792	    }
793	    std::size_t count = queue_->CancelOrder(req->order_id);
794	    if (count > 0) {
795	      MarkStateDirty();
796	    }
797	    for (const auto& id : action_mission_ids) {
798	      CleanupMissionCancel(id, "mission canceled by operator");
799	    }
800	    resp->success = true;
801	    resp->canceled_count = static_cast<uint32_t>(count);
802	    resp->message = "Order canceled, count=" + std::to_string(count);
803	    ReArmQueueStartRequest();
804	    return;
805	  }
806	  resp->success = false;
807	  resp->message = "Neither mission_id nor order_id specified";
808	}
