866	void DispatcherNode::ForceClearVda5050LinkCb(
867	    const std::shared_ptr<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Request> req,
868	    std::shared_ptr<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Response> resp) {
869	  // Task 7（终审 I1 闭合）：核心纯函数决策（fleet::PlanForceClearLink）+ 本地落地执行。
870	  // 决策规则集中在核心（零 ROS 依赖，可单测）：仅受理"受管清单内且当前离线"的车辆；
871	  // 锁归属必须经 mission->vehicle 绑定反查（严禁用"路径存档存在"之类的间接证据推断）。
872	  amr_dispatcher_core::fleet::ForceClearLinkRequest decision_req;
873	  decision_req.vehicle_id = req->vehicle_id;
874	  decision_req.confirm_vehicle_id = req->confirm_vehicle_id;
875	  decision_req.operator_id = req->operator_id;
876	  decision_req.reason = req->reason;
877	  decision_req.vehicle_in_managed_list = IsManagedVda5050Vehicle(req->vehicle_id);
878	  decision_req.vehicle_online = IsVehicleOnline(req->vehicle_id);
879	  decision_req.vehicle_quarantined = IsVehicleQuarantined(req->vehicle_id);
880	  decision_req.mission_vehicle_bindings = vda5050_mission_vehicle_;
881	  if (reservation_table_) {
882	    for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
883	      decision_req.held_locks[resource_id] = owner;
884	    }
885	  }
886	  const auto decision = amr_dispatcher_core::fleet::PlanForceClearLink(decision_req);
887	  if (!decision.allowed) {
888	    resp->success = false;
889	    resp->message = decision.reject_reason;
890	    return;
891	  }
892	
893	  // ---- 1) 释放该车名下锁（先于任务收口，保证 released_resources 可取证）----
894	  std::vector<std::string> released;
895	  if (reservation_table_) {
896	    for (const auto& [mission_id, ids] : decision.locks_by_mission) {
897	      const auto freed = reservation_table_->ReleaseResources(mission_id, ids);
898	      released.insert(released.end(), freed.begin(), freed.end());
899	    }
900	  }
901	  resp->released_resources.assign(released.begin(), released.end());
902	
903	  // ---- 2) 收口该车承接的在途任务 ----
904	  // 车辆已死，其承接的 mission 永远不会到达/完成，会一直占着 active_missions_ 与
905	  // 单车执行槽位，后续任务永远排不上（挂起守卫解除也派不出去）。
906	  // 人工强清 = 操作员宣告该任务作废：**全量释放 + 不重试 + 不回坞**，让队列立刻前进。
907	  // 不能走 FailMission：其恢复行为树可能判定 retry/dock（把死车任务重新入队），
908	  // 且资源释放取决于 BT 决策（可能保留锁），与"人工强解"语义相悖。
909	  for (const auto& mission_id : decision.missions_to_abort) {
910	    RCLCPP_WARN(get_logger(),
911	                "VDA 5050 force-clear: aborting in-flight mission %s bound to dead vehicle %s",
912	                mission_id.c_str(), req->vehicle_id.c_str());
913	    // 单车执行槽位释放 + 停车（否则槽位残留，后续任务永远无法派发）
914	    if (IsMissionTracked(mission_id)) {
915	      ReleaseTrackingSlot(mission_id);
916	      PublishStopPathForMission(mission_id);
917	    }
918	    {
919	      std::lock_guard<std::mutex> lock(active_missions_mutex_);
920	      active_missions_.erase(mission_id);
921	    }
922	    if (reservation_table_) {
923	      reservation_table_->Release(mission_id);  // 全量释放该任务名下锁
924	    }
925	    FinishExecuteGoal(mission_id, ExecuteFinish::kAbort,
926	                      "operator force-cleared offline VDA 5050 link", 1);
927	    mission_dispatch_time_.erase(mission_id);
928	    ForgetMissionDispatchState(mission_id);
929	    if (event_pub_ && event_pub_->is_activated()) {
930	      amr_dispatcher_interfaces::msg::MissionEvent msg;
931	      msg.stamp = now();
932	      msg.mission_id = mission_id;
933	      msg.event = "failed";
934	      msg.from_state = "ACTIVE";
935	      msg.to_state = "FAILED";
936	      msg.reason = "operator force-cleared offline VDA 5050 link for vehicle " + req->vehicle_id;
937	      event_pub_->publish(msg);
938	    }
939	  }
940	  ReArmQueueStartRequest();  // 队列后续任务需重新武装启动请求
941	
942	  // ---- 3) 车辆转入隔离态（**不摘除**受管清单）----
943	  // 评审 P0.5：通信失联不等于可以释放路权。强清后车辆仍然可见、可审计，
944	  // 但不再参与自动分配（选车时 quarantined -> 不合格），需显式恢复。
945	  SetVehicleQuarantined(req->vehicle_id, true);
946	  resp->quarantined = true;
947	  MarkStateDirty();
948	
949	  // ---- 4) 审计与响应 ----
950	  resp->success = true;
951	  resp->message = "Force-cleared offline link for " + req->vehicle_id + ", released " +
952	                  std::to_string(released.size()) + " resource(s) | reason: " + req->reason +
953	                  " | operator: " + req->operator_id +
954	                  " | vehicle QUARANTINED (not auto-assignable until restored; physical "
955	                  "position NOT machine-verified — operator bears that risk)";
956	  RCLCPP_WARN(get_logger(),
957	              "VDA 5050 link %s FORCE-CLEARED by operator %s (reason=\"%s\", released %zu "
958	              "resource(s) [%s]) -> vehicle QUARANTINED; physical position NOT verified",
959	              req->vehicle_id.c_str(), req->operator_id.c_str(), req->reason.c_str(),
960	              released.size(),
961	              [&released]() {
962	                std::string joined;
963	                for (std::size_t i = 0; i < released.size(); ++i) {
964	                  if (i) joined += ",";
965	                  joined += released[i];
966	                }
967	                return joined;
968	              }()
969	                  .c_str());
970	  // 审计落盘（audit_log_file 为空时只保留上面的 RCLCPP_WARN）
971	  AppendAudit("force_clear", req->vehicle_id, "", req->operator_id, req->reason, released);
972	}
