974	void DispatcherNode::RestoreVda5050LinkCb(
975	    const std::shared_ptr<amr_dispatcher_interfaces::srv::RestoreVda5050Link::Request> req,
976	    std::shared_ptr<amr_dispatcher_interfaces::srv::RestoreVda5050Link::Response> resp) {
977	  // 评审 P0.5：恢复 = 解除隔离，使车辆重新参与自动分配。
978	  // 准入校验下沉核心（PlanRestoreLink）：须已隔离 + 在线 + 操作员已核实位置。
979	  amr_dispatcher_core::fleet::RestoreLinkRequest decision_req;
980	  decision_req.vehicle_id = req->vehicle_id;
981	  decision_req.confirm_vehicle_id = req->confirm_vehicle_id;
982	  decision_req.operator_id = req->operator_id;
983	  decision_req.reason = req->reason;
984	  decision_req.vehicle_in_managed_list = IsManagedVda5050Vehicle(req->vehicle_id);
985	  decision_req.vehicle_quarantined = IsVehicleQuarantined(req->vehicle_id);
986	  decision_req.vehicle_online = IsVehicleOnline(req->vehicle_id);
987	  decision_req.position_verified = req->position_verified;
988	
989	  const auto decision = amr_dispatcher_core::fleet::PlanRestoreLink(decision_req);
990	  if (!decision.allowed) {
991	    resp->success = false;
992	    resp->message = decision.reject_reason;
993	    return;
994	  }
995	  SetVehicleQuarantined(req->vehicle_id, false);
996	  MarkStateDirty();
997	  AppendAudit("restore", req->vehicle_id, "", req->operator_id, req->reason);
998	  resp->success = true;
999	  resp->message = "Restored vehicle " + req->vehicle_id + " to dispatch pool | reason: " +
1000	                  req->reason + " | operator: " + req->operator_id;
1001	  RCLCPP_WARN(get_logger(),
1002	              "VDA 5050 link %s RESTORED by operator %s (reason=\"%s\", position_verified=%d) "
1003	              "-> vehicle re-enters automatic assignment",
1004	              req->vehicle_id.c_str(), req->operator_id.c_str(), req->reason.c_str(),
1005	              req->position_verified ? 1 : 0);
1006	  ReArmQueueStartRequest();  // 池中多了一台车 -> 唤醒排队任务重试
1007	}
