1009	void DispatcherNode::EnqueueMissionCb(
1010	    const std::shared_ptr<amr_dispatcher_interfaces::srv::EnqueueMission::Request> req,
1011	    std::shared_ptr<amr_dispatcher_interfaces::srv::EnqueueMission::Response> resp) {
1012	  if (!queue_) {
1013	    resp->success = false;
1014	    resp->message = "Dispatcher unconfigured";
1015	    resp->queue_size = 0;
1016	    return;
1017	  }
1018	  amr_dispatcher_core::dispatcher::Mission m;
1019	  StampMissionIdentity(m, next_sequence_);  // B4：id/sequence 同源
1020	  m.order_id = req->mission_file;
1021	  m.priority = req->priority;
1022	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
1023	  // 显式指定承接车辆（空 = 由选车策略决定）
1024	  m.assigned_vehicle_id = req->assigned_vehicle_id;
1025	  auto push_res = queue_->Push(m);
1026	  resp->success = push_res.accepted;
1027	  resp->message = push_res.accepted ? "Mission enqueued: " + m.id : push_res.message;
1028	  resp->queue_size = static_cast<int32_t>(queue_->size());
1029	
1030	  if (push_res.accepted) {
1031	    // 启动决策走 queued_mission_start 行为树（start_if_idle 且当前空闲才立即启动）
1032	    amr_dispatcher_bt::QueuedMissionStartBehaviorTreeInput start_input;
1033	    start_input.request.start_if_idle = req->start_if_idle;
1034	    start_input.request.mission_active = !HasFreeVehicleSlot();
1035	    const auto start_bt = amr_dispatcher_bt::TickQueuedMissionStartBehaviorTree(start_input);
1036	    if (start_bt.success && start_bt.decision.request_queue_start) {
1037	      queue_start_requested_ = true;
1038	    }
1039	    RCLCPP_INFO(get_logger(), "EnqueueMission via BT: branch=%s request_queue_start=%d",
1040	                start_bt.branch.c_str(), start_bt.decision.request_queue_start ? 1 : 0);
1041	  }
1042	}
1043	
1044	void DispatcherNode::CancelQueuedMissionCb(
1045	    const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Request> req,
1046	    std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Response> resp) {
1047	  if (!queue_) {
1048	    resp->success = false;
1049	    resp->message = "Dispatcher unconfigured";
1050	    resp->queue_size = 0;
1051	    return;
1052	  }
1053	  bool canceled = queue_->Cancel(req->mission_id);
1054	  if (canceled) {
1055	    // 排队取消命中：收口该任务的 action goal/handle 预占/pending_nav（审查 I5）
1056	    CleanupMissionCancel(req->mission_id, "mission canceled by operator");
1057	  } else {
1058	    // 按整单取消：取消前取证该订单在队任务，取消成功后逐个收口（审查 I5）
1059	    std::vector<std::string> action_mission_ids;
1060	    if (!execute_goal_handles_.empty()) {
1061	      for (const auto& qm : queue_->Snapshot()) {
1062	        if (qm.order_id == req->mission_id) {
1063	          action_mission_ids.push_back(qm.id);
1064	        }
1065	      }
1066	    }
1067	    const std::size_t order_count = queue_->CancelOrder(req->mission_id);
1068	    canceled = (order_count > 0);
1069	    for (const auto& id : action_mission_ids) {
1070	      CleanupMissionCancel(id, "mission canceled by operator");
1071	    }
1072	  }
1073	  if (req->cancel_active) {
1074	    bool erased = false;
1075	    {
1076	      std::lock_guard<std::mutex> lock(active_missions_mutex_);
1077	      erased = (active_missions_.erase(req->mission_id) > 0);
1078	    }
1079	    if (erased) {
1080	      canceled = true;
1081	      if (reservation_table_) {
1082	        reservation_table_->Release(req->mission_id);
1083	      }
1084	      // 若被取消的是正在跟踪 /plan 的任务，发空路径停车
1085	      if (IsMissionTracked(req->mission_id)) {
1086	        ReleaseTrackingSlot(req->mission_id);
1087	        PublishStopPathForMission(req->mission_id);
1088	      }
1089	      // 活动任务取消同样收口 action goal 与在途导航 goal（cancel_active 路径，审查 I5）
1090	      CleanupMissionCancel(req->mission_id, "mission canceled by operator");
1091	    }
1092	  }
1093	  resp->success = canceled;
1094	  resp->message = canceled ? "Mission canceled: " + req->mission_id : "Mission not found: " + req->mission_id;
1095	  resp->queue_size = static_cast<int32_t>(queue_->size());
1096	}
