1133	void DispatcherNode::EstimateMissionCostCb(
1134	    const std::shared_ptr<amr_dispatcher_interfaces::srv::EstimateMissionCost::Request> req,
1135	    std::shared_ptr<amr_dispatcher_interfaces::srv::EstimateMissionCost::Response> resp) {
1136	  // B5：真实现——mission_file 作为站点对编码（"from->to" 或 "from:to"），
1137	  // 用 StationCatalog 直线距离和喂 EstimateDistanceCost；电池参数无 srv 字段，
1138	  // 沿用核心测试约定（0.1 V/m，最低 21.0 V 与 charging workflow 阈值一致）。
1139	  resp->mission_id = req->mission_file;
1140	
1141	  const std::string& spec = req->mission_file;
1142	  std::string from;
1143	  std::string to;
1144	  const auto arrow = spec.find("->");
1145	  if (arrow != std::string::npos) {
1146	    from = spec.substr(0, arrow);
1147	    to = spec.substr(arrow + 2);
1148	  } else {
1149	    const auto colon = spec.find(':');
1150	    if (colon != std::string::npos) {
1151	      from = spec.substr(0, colon);
1152	      to = spec.substr(colon + 1);
1153	    }
1154	  }
1155	  if (from.empty() || to.empty()) {
1156	    resp->success = false;
1157	    resp->message = "mission_file must encode a station pair as 'from->to' or 'from:to', got: " + spec;
1158	    return;
1159	  }
1160	  if (!catalog_reloader_ || !catalog_reloader_->loaded()) {
1161	    resp->success = false;
1162	    resp->message = "station catalog not loaded";
1163	    return;
1164	  }
1165	  const auto& catalog = catalog_reloader_->catalog();
1166	  const auto* from_st = amr_dispatcher_core::catalog::FindStation(catalog, from);
1167	  const auto* to_st = amr_dispatcher_core::catalog::FindStation(catalog, to);
1168	  if (!from_st || !to_st) {
1169	    resp->success = false;
1170	    resp->message = "unknown station(s) in mission_file '" + spec + "'";
1171	    return;
1172	  }
1173	
1174	  const double distance_m =
1175	      std::hypot(to_st->x - from_st->x, to_st->y - from_st->y);
1176	  constexpr int kTwoStationWaypoints = 2;  // 取/送 2 站点 = 1 航段
1177	  constexpr double kBatteryDropPerMeter = 0.1;    // 单位里程压降（V/m）
1178	  constexpr double kMinimumBatteryVoltage = 21.0; // 与 charging workflow 阈值一致
1179	
1180	  const auto estimate = amr_dispatcher_core::workflow::EstimateDistanceCost(
1181	      distance_m, kTwoStationWaypoints, req->nominal_speed_mps, req->battery_voltage,
1182	      kBatteryDropPerMeter, kMinimumBatteryVoltage, "station_catalog_straight");
1183	
1184	  resp->success = true;
1185	  resp->message = "estimated via station catalog straight-line distance";
1186	  resp->waypoint_count = estimate.waypoint_count;
1187	  resp->distance_m = estimate.distance_m;
1188	  resp->eta_sec = estimate.eta_sec;
1189	  resp->battery_drop_v = estimate.battery_drop_v;
1190	  resp->projected_battery_voltage = estimate.projected_battery_voltage;
1191	  resp->battery_sufficient = estimate.battery_sufficient;
1192	}
