1209	void DispatcherNode::DetectTrafficDeadlockCb(
1210	    const std::shared_ptr<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock::Request> /*req*/,
1211	    std::shared_ptr<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock::Response> resp) {
1212	  if (!deadlock_detector_) {
1213	    resp->success = false;
1214	    resp->deadlocked = false;
1215	    resp->message = "Deadlock detector unconfigured";
1216	    return;
1217	  }
1218	  // 快照组包与 DeadlockTick 共用 helper：服务入口与定时检测结论不分叉；
1219	  // 沿用本回调既有的 active_missions_ 加锁约定（helper 自身不带锁）
1220	  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
1221	  {
1222	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1223	    snap = BuildDeadlockSnapshot();
1224	  }
1225	  const auto findings = deadlock_detector_->Detect(snap);
1226	  resp->success = true;
1227	  resp->deadlocked = !findings.empty();
1228	  resp->message = resp->deadlocked ? "Deadlock detected in graph" : "No deadlock detected";
1229	  for (const auto& f : findings) {
1230	    for (const auto& mid : f.mission_ids) {
1231	      resp->mission_ids.push_back(mid);
1232	    }
1233	    // cycle_path 为任务/资源交替闭合序列：奇数位才是资源 id（任务 id 不得混入）
1234	    for (std::size_t i = 1; i < f.cycle_path.size(); i += 2) {
1235	      resp->conflict_resource_ids.push_back(f.cycle_path[i]);
1236	    }
1237	    resp->descriptions.push_back(f.description);
1238	  }
1239	}
