1298	  // B5：真实现——BuildOperatorSnapshotProjection 字段全量投影。
1299	  // 无 fleet/facility/business 后端时对应字段传 nullptr 透传为空集合。
1300	  amr_dispatcher_core::workflow::OperatorSnapshotRequest snap_req;
1301	  {
