1310	  }
1311	
1312	  if (queue_) {
1313	    for (const auto& m : queue_->Snapshot()) {
1314	      amr_dispatcher_core::workflow::QueuedMission qm;
1315	      qm.profile.mission_id = m.id;
1316	      qm.mission_file = m.order_id;
1317	      qm.priority = m.priority;
1318	      qm.sequence = m.sequence;
1319	      snap_req.mission_queue.push_back(qm);
1320	      // 队列按 order_id 记暂停：探测本任务所属订单是否被暂停
1321	      if (!m.order_id.empty() && queue_->IsOrderPaused(m.order_id)) {
1322	        snap_req.paused_workflow_order_ids.insert(m.order_id);
1323	      }
1324	    }
