1338	      wfe.recoverable = evt.recoverable;
1339	      snap_req.mission_events.push_back(wfe);
1340	    }
1341	  }
1342	  snap_req.event_limit = req->event_limit;
1343	
1344	  const auto proj = amr_dispatcher_core::workflow::BuildOperatorSnapshotProjection(snap_req);
1345	  resp->success = proj.success;
1346	  resp->message = proj.message;
