1381	void DispatcherNode::ValidateSiteConfigCb(
1382	    const std::shared_ptr<amr_dispatcher_interfaces::srv::ValidateSiteConfig::Request> req,
1383	    std::shared_ptr<amr_dispatcher_interfaces::srv::ValidateSiteConfig::Response> resp) {
1384	  // B5：真实现——真实尝试加载 stations_file；同时校验 dispatcher 最小参数集合。
1385	  // bundle_dir 指定 bundle 时优先用 <bundle_dir>/stations.yaml，否则回退节点参数路径。
1386	  resp->version_id = req->version_id.empty() ? "v1.0.0" : req->version_id;
1387	
1388	  std::string stations_path = get_parameter("stations_file").as_string();
1389	  if (!req->bundle_dir.empty()) {
1390	    stations_path = req->bundle_dir + "/stations.yaml";
1391	  }
1392	  resp->checked_files.push_back(stations_path);
1393	
1394	  const auto catalog_opt = amr_dispatcher_core::catalog::LoadStationCatalog(stations_path);
1395	  if (!catalog_opt) {
1396	    resp->success = false;
1397	    resp->errors.push_back("stations_file load failed: " + stations_path);
1398	    resp->message = "validation failed: " + stations_path + " not parseable";
1399	    return;
1400	  }
1401	  if (catalog_opt->stations.empty()) {
1402	    resp->success = false;
1403	    resp->errors.push_back("stations catalog empty: " + stations_path);
1404	    resp->message = "validation failed: no stations defined";
1405	    return;
1406	  }
1407	
1408	  // 最小参数集合校验：任一失败即整体失败
1409	  const int queue_capacity = get_parameter("queue_capacity").as_int();
1410	  if (queue_capacity <= 0) {
1411	    resp->errors.push_back("queue_capacity must be > 0, got " + std::to_string(queue_capacity));
1412	  }
1413	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
1414	  if (sched_hz <= 0.0) {
1415	    resp->errors.push_back("schedule_rate_hz must be > 0, got " + std::to_string(sched_hz));
1416	  }
1417	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
1418	  if (deadlock_hz <= 0.0) {
1419	    resp->errors.push_back("deadlock_check_rate_hz must be > 0, got " + std::to_string(deadlock_hz));
1420	  }
1421	  const int max_active = get_parameter("max_active_missions").as_int();
1422	  if (max_active < 1) {
1423	    resp->errors.push_back("max_active_missions must be >= 1, got " + std::to_string(max_active));
1424	  }
1425	  const std::string comparator = get_parameter("comparator").as_string();
1426	  if (!amr_dispatcher_core::dispatcher::CreateMissionComparator(comparator)) {
1427	    resp->errors.push_back("unknown comparator: " + comparator);
1428	  }
1429	
1430	  resp->success = resp->errors.empty();
1431	  resp->message = resp->success
1432	                      ? "site configuration validation passed"
1433	                      : "validation failed: " + std::to_string(resp->errors.size()) + " error(s)";
1434	}
