1436	rclcpp_action::GoalResponse DispatcherNode::HandleGoal(
1437	    const rclcpp_action::GoalUUID& /*uuid*/,
1438	    std::shared_ptr<const ExecuteMission::Goal> goal) {
1439	  if (!goal || goal->mission_id.empty()) {
1440	    RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: empty mission_id");
1441	    return rclcpp_action::GoalResponse::REJECT;
1442	  }
1443	  if ((queue_ && queue_->Contains(goal->mission_id)) ||
1444	      active_missions_.count(goal->mission_id) > 0) {
1445	    RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: duplicate mission_id %s",
1446	                goal->mission_id.c_str());
1447	    return rclcpp_action::GoalResponse::REJECT;
1448	  }
1449	  // required_resources 可预占：Reserve 原子性（不落任何锁即失败），失败即 REJECT
1450	  if (!goal->required_resources.empty()) {
1451	    if (!reservation_table_) {
1452	      RCLCPP_WARN(get_logger(),
1453	                  "ExecuteMission goal rejected: reservation table unavailable for %s",
1454	                  goal->mission_id.c_str());
1455	      return rclcpp_action::GoalResponse::REJECT;
1456	    }
1457	    auto res = reservation_table_->Reserve(goal->mission_id, goal->required_resources);
1458	    if (!res.success) {
1459	      RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: reserve failed for %s: %s",
1460	                  goal->mission_id.c_str(), res.message.c_str());
1461	      return rclcpp_action::GoalResponse::REJECT;
1462	    }
1463	  }
1464	  // DEFER + HandleAccepted 里显式 execute()：不受框架是否隐式 execute 影响的稳妥路径
1465	  return rclcpp_action::GoalResponse::ACCEPT_AND_DEFER;
1466	}
