1468	rclcpp_action::CancelResponse DispatcherNode::HandleCancel(
1469	    const std::shared_ptr<GoalHandleExecute> goal_handle) {
1470	  if (execute_goal_handles_.find(goal_handle->get_goal()->mission_id) ==
1471	      execute_goal_handles_.end()) {
1472	    return rclcpp_action::CancelResponse::REJECT;
1473	  }
1474	  // 只受理取消请求：rclcpp_action 在本回调返回 ACCEPT 之后才把 goal 迁移到
1475	  // CANCELING，而 canceled() 只允许在 CANCELING 态调用——
1476	  // 实际的任务取消与 goal 终结延后到 ProcessActionCancels（ScheduleTick 内）。
1477	  return rclcpp_action::CancelResponse::ACCEPT;
