1480	void DispatcherNode::HandleAccepted(const std::shared_ptr<GoalHandleExecute> goal_handle) {
1481	  const auto goal = goal_handle->get_goal();
1482	  // ACCEPTED -> EXECUTING：后续 publish_feedback/succeed/abort 的前置条件
1483	  goal_handle->execute();
1484	
1485	  if (!queue_) {
1486	    if (reservation_table_) {
1487	      reservation_table_->Release(goal->mission_id);
1488	    }
1489	    auto result = std::make_shared<ExecuteMission::Result>();
1490	    result->success = false;
1491	    result->error_code = 1;
1492	    result->message = "dispatcher not configured";
1493	    goal_handle->abort(result);
1494	    return;
1495	  }
1496	
1497	  amr_dispatcher_core::dispatcher::Mission m;
1498	  m.id = goal->mission_id;
1499	  m.order_id = goal->mission_id;  // 订单号=任务号，保证整单取消可寻址
1500	  m.priority = goal->priority;
1501	  m.dropoff_station = goal->target_station;
1502	  if (goal->deadline_seconds > 0.0) {
1503	    m.deadline_unix_ms =
1504	        std::chrono::duration_cast<std::chrono::milliseconds>(
1505	            std::chrono::system_clock::now().time_since_epoch())
1506	            .count() +
1507	        static_cast<std::int64_t>(goal->deadline_seconds * 1000.0);
1508	  }
1509	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
1510	  m.sequence = next_sequence_++;
1511	
1512	  auto push = queue_->Push(m);
1513	  if (!push.accepted) {
1514	    // 入队失败回滚 HandleGoal 的资源预占并 abort（死锁风险下的显式失败出口）
1515	    if (reservation_table_) {
1516	      reservation_table_->Release(m.id);
1517	    }
1518	    auto result = std::make_shared<ExecuteMission::Result>();
1519	    result->success = false;
1520	    result->error_code = 1;
1521	    result->message = "enqueue rejected: " + push.message;
1522	    goal_handle->abort(result);
1523	    RCLCPP_WARN(get_logger(), "ExecuteMission enqueue rejected for %s: %s", m.id.c_str(),
1524	                push.message.c_str());
1525	    return;
1526	  }
1527	
1528	  execute_goal_handles_[m.id] = goal_handle;
1529	  queue_start_requested_ = true;  // action 提交的任务武装 runtime 出队启动请求
1530	  RCLCPP_INFO(get_logger(),
1531	              "ExecuteMission accepted: %s -> queued (target=%s, prio=%d, resources=%zu)",
1532	              m.id.c_str(), m.dropoff_station.c_str(), m.priority,
1533	              goal->required_resources.size());
1534	}
