1536	void DispatcherNode::FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
1537	                                        const std::string& message, std::int32_t error_code) {
1538	  auto it = execute_goal_handles_.find(mission_id);
1539	  if (it == execute_goal_handles_.end()) {
1540	    return;
1541	  }
1542	  auto handle = it->second;
1543	  execute_goal_handles_.erase(it);
1544	
1545	  // total_duration_sec：按派发时刻计时（排队中取消等未派发场景为 0），
1546	  // 计时后即遗忘时间戳，防止 map 长期驻留
1547	  double duration_sec = 0.0;
1548	  auto dispatch_time = mission_dispatch_time_.find(mission_id);
1549	  if (dispatch_time != mission_dispatch_time_.end()) {
1550	    duration_sec = std::chrono::duration<double>(
1551	                       std::chrono::steady_clock::now() - dispatch_time->second)
1552	                       .count();
1553	    mission_dispatch_time_.erase(dispatch_time);
1554	  }
1555	  if (!handle || !handle->is_active()) {
1556	    return;
1557	  }
1558	
1559	  auto result = std::make_shared<ExecuteMission::Result>();
1560	  result->success = (kind == ExecuteFinish::kSucceed);
1561	  result->error_code = error_code;
1562	  result->message = message;
1563	  result->total_duration_sec = duration_sec;
1564	  try {
1565	    if (handle->is_canceling()) {
1566	      // 已受理 action cancel：只能走 canceled()（rclcpp_action 状态机约束）
1567	      handle->canceled(result);
1568	    } else if (handle->is_executing()) {
1569	      if (kind == ExecuteFinish::kSucceed) {
1570	        handle->succeed(result);
1571	      } else {
1572	        // kAbort 与服务侧取消（未进入 CANCELING 无法 canceled()）降级为 abort
1573	        handle->abort(result);
1574	      }
1575	    } else {
1576	      // ACCEPTED 未执行的兜底：先 execute 再 abort，避免 rclcpp_action 状态断言
1577	      handle->execute();
1578	      handle->abort(result);
1579	    }
1580	    RCLCPP_INFO(get_logger(), "ExecuteMission goal finished: %s kind=%d (%s)",
1581	                mission_id.c_str(), static_cast<int>(kind), message.c_str());
1582	  } catch (const std::exception& ex) {
1583	    RCLCPP_ERROR(get_logger(), "FinishExecuteGoal(%s) failed: %s", mission_id.c_str(), ex.what());
1584	  }
1585	}
