1587	void DispatcherNode::CleanupMissionCancel(const std::string& mission_id,
1588	                                          const std::string& reason) {
1589	  // HandleGoal 预占的 required_resources 随任务取消一并释放（plan 模式无 handle 时
1590	  // Release 对无锁持有者是无操作，与既有行为一致）
1591	  const bool has_handle = execute_goal_handles_.count(mission_id) > 0;
1592	  if (has_handle && reservation_table_) {
1593	    reservation_table_->Release(mission_id);
1594	  }
1595	  // action 模式级联：取消在途 NavigateSequence goal 并清 pending 标记
1596	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1597	    if (nav_client_ && pending_nav_goal_handle_) {
1598	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1599	    }
1600	    pending_nav_mission_id_.clear();
1601	    pending_nav_goal_handle_.reset();
1602	  }
1603	  if (has_handle) {
1604	    // 服务侧取消未受理 action cancel（handle 不在 CANCELING），降级 abort(3 PREEMPTED)
1605	    // （total_duration_sec 的时间戳由 FinishExecuteGoal 计时后遗忘）
1606	    FinishExecuteGoal(mission_id, ExecuteFinish::kCanceled, reason, 3);
1607	  } else {
1608	    mission_dispatch_time_.erase(mission_id);
1609	  }
1610	  ForgetMissionDispatchState(mission_id);
1611	}
