1630	void DispatcherNode::ForgetMissionDispatchState(const std::string& mission_id) {
1631	  // 路由锁预留记账、排队等待记录与派发起点同步遗忘：
1632	  // 幂等，供 Complete/Fail/取消/死锁取消/预占判负等终态路径共用
1633	  mission_reserved_at_.erase(mission_id);
1634	  pending_wait_.erase(mission_id);
1635	  in_flight_pending_wait_.erase(mission_id);
1636	  mission_dispatch_start_.erase(mission_id);
1637	  mission_route_paths_.erase(mission_id);  // Task 5：行驶路径存档随终态遗忘
1638	  vda5050_mission_vehicle_.erase(mission_id);  // Task 7：mission->车辆绑定随终态遗忘
1639	  // B3：时空窗占用随终态全清（任务结束 = 不再占用任何资源）
1640	  ReleaseAllTimeSpaceForMission(mission_id);
1641	}
