1643	void DispatcherNode::ProcessActionCancels() {
1644	  if (execute_goal_handles_.empty()) {
1645	    return;
1646	  }
1647	  std::vector<std::string> canceling;
1648	  canceling.reserve(execute_goal_handles_.size());
1649	  for (const auto& [id, handle] : execute_goal_handles_) {
1650	    if (handle && handle->is_canceling()) {
1651	      canceling.push_back(id);
1652	    }
1653	  }
1654	  for (const auto& id : canceling) {
1655	    RCLCPP_INFO(get_logger(), "ExecuteMission cancel accepted by action client: %s", id.c_str());
1656	    bool canceled = false;
1657	    if (queue_ && queue_->Cancel(id)) {
1658	      // 排队中任务被 action 取消：连带释放 HandleGoal 预占的 required_resources
1659	      if (reservation_table_) {
1660	        reservation_table_->Release(id);
1661	      }
1662	      canceled = true;
1663	    } else {
1664	      auto it = active_missions_.find(id);
1665	      if (it != active_missions_.end()) {
1666	        if (reservation_table_) {
1667	          reservation_table_->Release(id);
1668	        }
1669	        if (IsMissionTracked(id)) {
1670	          ReleaseTrackingSlot(id);
1671	          PublishStopPathForMission(id);
1672	        }
1673	        active_missions_.erase(it);
1674	        canceled = true;
1675	      }
1676	    }
1677	    ForgetMissionDispatchState(id);  // 取消终态：路由锁记账/等待记录/派发起点遗忘
1678	    // action 模式级联：取消在途的 NavigateSequence goal 并清 pending 标记
1679	    if (navigation_backend_ == "action" && pending_nav_mission_id_ == id) {
1680	      if (nav_client_ && pending_nav_goal_handle_) {
1681	        nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1682	      }
1683	      pending_nav_mission_id_.clear();
1684	      pending_nav_goal_handle_.reset();
1685	    }
1686	    // 此时 handle 已确认 is_canceling()，canceled() 状态合法
1687	    FinishExecuteGoal(id, ExecuteFinish::kCanceled, "mission canceled by action client", 3);
1688	    if (canceled) {
1689	      ReArmQueueStartRequest();
1690	    }
1691	  }
1692	}
