1694	void DispatcherNode::NavGoalResponseCb(const std::string& mission_id,
1695	                                       const GoalHandleNavigate::SharedPtr& goal_handle) {
1696	  if (!goal_handle) {
1697	    RCLCPP_WARN(get_logger(), "NavigateSequence goal rejected by bridge for mission %s",
1698	                mission_id.c_str());
1699	    if (pending_nav_mission_id_ == mission_id) {
1700	      pending_nav_mission_id_.clear();
1701	      pending_nav_goal_handle_.reset();
1702	    }
1703	    // FailMission 内部会清理 tracking 槽位与空路径停车
1704	    FailMission(mission_id, "navigate_sequence goal rejected by bridge");
1705	    return;
1706	  }
1707	  // goal 响应到达时任务可能已被取消/完结：孤儿 goal 直接取消，
1708	  // 否则 bridge 盲跑 + pending 句柄残留（审查 I4）
1709	  bool mission_alive;
1710	  {
1711	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1712	    mission_alive = active_missions_.count(mission_id) > 0;
1713	  }
1714	  if (!mission_alive) {
1715	    RCLCPP_WARN(get_logger(),
1716	                "Stale NavigateSequence goal response for %s (mission gone); canceling orphan goal",
1717	                mission_id.c_str());
1718	    nav_client_->async_cancel_goal(goal_handle);
1719	    if (pending_nav_mission_id_ == mission_id) {
1720	      pending_nav_mission_id_.clear();
1721	      pending_nav_goal_handle_.reset();
1722	    }
1723	    return;
1724	  }
1725	  pending_nav_goal_handle_ = goal_handle;
1726	}
