1728	void DispatcherNode::NavFeedbackCb(
1729	    const std::string& mission_id, const GoalHandleNavigate::SharedPtr& /*goal_handle*/,
1730	    const std::shared_ptr<const NavigateSequence::Feedback> feedback) {
1731	  mission_last_progress_[mission_id] = std::chrono::steady_clock::now();  // 喂死锁 idle 启发式
1732	  if (!feedback) {
1733	    return;
1734	  }
1735	  // NavigateSequence feedback -> ExecuteMission feedback 映射
1736	  // （current_index/total -> state_code=2 EXECUTING + percent=index/total*100）
1737	  auto hit = execute_goal_handles_.find(mission_id);
1738	  if (hit == execute_goal_handles_.end() || !hit->second || !hit->second->is_executing()) {
1739	    return;
1740	  }
1741	  auto fb = std::make_shared<ExecuteMission::Feedback>();
1742	  fb->state_code = 2;  // EXECUTING
1743	  fb->current_node = feedback->current_station;
1744	  fb->percent_complete =
1745	      feedback->total_waypoints > 0
1746	          ? static_cast<float>(100.0 * static_cast<double>(feedback->current_index) /
1747	                               static_cast<double>(feedback->total_waypoints))
1748	          : 0.0f;
1749	  fb->estimated_remaining_sec = 0.0;
1750	  hit->second->publish_feedback(fb);
1751	}
