1753	void DispatcherNode::NavResultCb(const std::string& mission_id,
1754	                                 const GoalHandleNavigate::WrappedResult& result) {
1755	  if (pending_nav_mission_id_ == mission_id) {
1756	    pending_nav_mission_id_.clear();
1757	    pending_nav_goal_handle_.reset();
1758	  }
1759	  if (result.code == rclcpp_action::ResultCode::SUCCEEDED && result.result &&
1760	      result.result->success) {
1761	    CompleteMission(mission_id, "navigate_sequence succeeded");
1762	    return;
1763	  }
1764	  std::string msg;
1765	  if (result.result && !result.result->message.empty()) {
1766	    msg = result.result->message;
1767	  } else if (result.code == rclcpp_action::ResultCode::CANCELED) {
1768	    msg = "navigate_sequence canceled";
1769	  } else if (result.code == rclcpp_action::ResultCode::ABORTED) {
1770	    msg = "navigate_sequence aborted";
1771	  } else {
1772	    msg = "navigate_sequence failed";
1773	  }
1774	  FailMission(mission_id, msg);
1775	}
