1788	
1789	bool DispatcherNode::ScheduleGatesPass() {
1790	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1791	  ProcessActionCancels();
1792	
1793	  // 批次 2：防抖状态落盘。放在所有提前 return 之前，保证即使队列空/门禁
1794	  // 阻断也照样把"已变更"的状态写下去（否则最后一次变更可能永远不落盘）。
1795	  if (state_snapshot_dirty_ && !state_snapshot_file_.empty()) {
1796	    const auto elapsed = std::chrono::duration<double>(
1797	                             std::chrono::steady_clock::now() - state_snapshot_dirty_at_)
1798	                             .count();
1799	    if (elapsed >= state_snapshot_debounce_sec_) {
1800	      FlushStateSnapshot();
1801	    }
1802	  }
1803	
1804	  // Task 5 Rule 2（Spec §5.2）：每 tick 先巡检受管小车链路。
1805	  // 离线 -> 挂起新派发（不消费 queue_start_requested_，恢复后自动继续）、
1806	  // 锁一律保留；在线但 state 陈旧 -> 仅软看门狗告警。受管清单为空时零开销跳过。
1807	  if (EnforceVda5050LinkGuard()) {
1808	    return false;
1809	  }
1810	
1811	  // 批次 6.2：低电量自动插充电单（默认关闭；开着才扫车）。
1812	  // 放在门禁之前：队列空时正是插充电单的时机，且插单本身要武装启动请求。
1813	  PlanAutoChargingTick();
1814	
1815	  // 无状态门禁判据（队列空 / 容量 / 空闲槽位 / 地图版本）聚合为纯函数：
1816	  // 判据的**优先顺序**（容量已超时不再报地图哈希不匹配）由 core 单测锁定。
1817	  const bool catalog_loaded = catalog_reloader_ != nullptr && catalog_reloader_->loaded();
1818	  amr_dispatcher_core::workflow::DispatchGateRequest gate_req;
1819	  gate_req.queue_empty = !queue_ || queue_->empty();
1820	  gate_req.active_mission_count = active_missions_.size();
1821	  gate_req.max_active_missions =
1822	      static_cast<std::size_t>(get_parameter("max_active_missions").as_int());
1823	  gate_req.has_free_vehicle_slot = HasFreeVehicleSlot();
1824	  gate_req.expected_map_hash = expected_map_hash_;
1825	  gate_req.catalog_loaded = catalog_loaded;
1826	  if (catalog_loaded) {
1827	    gate_req.catalog_map_hash = catalog_reloader_->catalog().map_hash;
1828	  }
1829	  const auto gate = amr_dispatcher_core::workflow::EvaluateDispatchGates(gate_req);
1830	  if (gate.map_gate_evaluated) {
1831	    map_version_valid_ = gate.map_version_valid;
1832	  }
1833	  switch (gate.kind) {
1834	    case amr_dispatcher_core::workflow::DispatchGateDecision::Kind::kPass:
1835	      break;
1836	    case amr_dispatcher_core::workflow::DispatchGateDecision::Kind::kQueueEmpty:
1837	    case amr_dispatcher_core::workflow::DispatchGateDecision::Kind::kCapacityExceeded:
1838	    case amr_dispatcher_core::workflow::DispatchGateDecision::Kind::kNoFreeVehicleSlot:
1839	      // 执行模型：每台受管车同时只跑一条 /plan（多车则可并发多条）。
1840	      // 无可用执行槽位 -> 本 tick 不派发（任务留队，等某台车完成或状态变化后重试）。
1841	      return false;
1842	    case amr_dispatcher_core::workflow::DispatchGateDecision::Kind::kMapVersionMismatch:
1843	      // 地图版本门禁：目录哈希缺失或与期望不一致 -> 环境地图与部署目录不匹配，
1844	      // 暂停出队派发。不消费 queue_start_requested_，哈希恢复一致后派发自动继续。
1845	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1846	                           "Map hash mismatch: expected %s, got %s, dispatching paused",
1847	                           expected_map_hash_.c_str(),
1848	                           gate_req.catalog_map_hash.empty() ? "<missing>"
1849	                                                             : gate_req.catalog_map_hash.c_str());
1850	      return false;
1851	  }
1852	
1853	  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1854	  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1855	  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1856	  runtime_input.tick.mission_active = !gate_req.has_free_vehicle_slot;
1857	  runtime_input.tick.queue_start_requested = queue_start_requested_;
1858	  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1859	  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1860	    return false;
1861	  }
1862	  queue_start_requested_ = false;  // 启动请求被本次派发消费
1863	  return true;
1864	}
