1866	std::optional<DispatcherNode::ReadyCandidate> DispatcherNode::SelectReadyCandidate() {
1867	  // ---- A6 选车（PeekN 扫描 + 三态处理 + 队首阻塞规避）----
1868	  // 队首任务可能因"暂无合格车辆"而不可派；此时**不能**让整条队列堵死：
1869	  // 扫描前 N 个排队任务，挑第一个能选到车且能预留锁的。
1870	  const int64_t scan_depth_param =
1871	      std::max<int64_t>(1, get_parameter("assignment_scan_depth").as_int());
1872	  const std::size_t scan_depth = static_cast<std::size_t>(scan_depth_param);
1873	  const auto candidates = queue_->PeekN(scan_depth);
1874	  if (candidates.empty()) {
1875	    return std::nullopt;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1876	  }
1877	
1878	  // ---- 组包（纯采集，无副作用）----
1879	  // 三态处置的顺序、"一 tick 只派一个"、"两类拒绝的记账/告警先后"都由
1880	  // core 的 PlanDispatchTick 产出有序 step 表达（DispatchTickPlanningTest 覆盖）。
1881	  amr_dispatcher_core::workflow::DispatchTickRequest tick_request;
1882	  tick_request.candidates.reserve(candidates.size());
1883	  std::unordered_map<std::string, amr_dispatcher_core::dispatcher::Mission> missions_by_id;
1884	  for (const auto& candidate_mission : candidates) {
1885	    amr_dispatcher_core::workflow::DispatchCandidate candidate;
1886	    candidate.mission = candidate_mission;
1887	    // 兼容红线：**legacy 单车模式**（既无 local_sim 受管车、也无 VDA 5050 受管车）
1888	    // 不走选车流程 —— 那里没有"车辆"概念，唯一的执行槽位是空串键
1889	    // （vehicle_current_mission_[""]），与改动前逐字等价。
1890	    // 若此处也调选车，request.vehicles 为空 -> 核心返回 kRejected
1891	    // ("no managed vehicles configured") -> 单车任务被永久判负（实测踩过）。
1892	    if (HasAnyManagedVehicle()) {
1893	      candidate.assignment = SelectVehicleForMission(candidate_mission);
1894	    } else {
1895	      candidate.assignment.outcome = amr_dispatcher_core::fleet::AssignmentOutcome::kAssigned;
1896	      candidate.assignment.strategy = "legacy_single_vehicle";
1897	    }
1898	    if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1899	      candidate.route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1900	          catalog_reloader_->catalog(), candidate_mission.pickup_station,
1901	          candidate_mission.dropoff_station);
1902	    }
1903	    missions_by_id.emplace(candidate_mission.id, candidate_mission);
1904	    tick_request.candidates.push_back(std::move(candidate));
1905	  }
1906	
1907	  // ---- 预留回调（唯一有副作用的一段，由 plan 按顺序驱动）----
1908	  //    time_space 模式：预约**带时间窗**的路权（多车可错峰并行），
1909	  //    整条路径全有或全无；static 模式：静态排他锁（现网行为）。
1910	  tick_request.try_reserve =
1911	      [this, &missions_by_id](const std::string& mission_id,
1912	                              const std::vector<std::string>& route_locks) {
1913	        amr_dispatcher_core::workflow::ReservationAttempt attempt;
1914	        if (UseTimeSpaceMode()) {
1915	          // 时空窗模式：不占静态排他锁，改为预约时间窗。
1916	          const auto mission_it = missions_by_id.find(mission_id);
1917	          std::vector<std::string> path_node_ids;
1918	          if (catalog_reloader_ != nullptr && catalog_reloader_->loaded() &&
1919	              mission_it != missions_by_id.end() &&
1920	              !mission_it->second.pickup_station.empty()) {
1921	            const auto route_path = amr_dispatcher_core::catalog::FindRoutePath(
1922	                catalog_reloader_->catalog(), mission_it->second.pickup_station,
1923	                mission_it->second.dropoff_station);
1924	            if (route_path.has_value()) {
1925	              path_node_ids = *route_path;
1926	            }
1927	          }
1928	          std::string ts_message;
1929	          if (!ReserveTimeSpaceForMission(mission_id, path_node_ids, &ts_message)) {
1930	            attempt.success = false;
1931	            attempt.denial_kind =
1932	                amr_dispatcher_core::workflow::ReservationAttempt::DenialKind::kTimeSpace;
1933	            attempt.message = ts_message;
1934	            return attempt;
1935	          }
1936	          attempt.success = true;
1937	          return attempt;
1938	        }
1939	        if (route_locks.empty() || !reservation_table_) {
1940	          attempt.success = true;
1941	          return attempt;
1942	        }
1943	        auto reserve = reservation_table_->Reserve(mission_id, route_locks);
1944	        if (!reserve.success) {
1945	          // 锁被占 -> 该单等锁（留队）；**不占用启动请求**，等锁释放时重试。
1946	          attempt.success = false;
1947	          attempt.denial_kind =
1948	              amr_dispatcher_core::workflow::ReservationAttempt::DenialKind::kStatic;
1949	          attempt.message = reserve.message;
1950	          return attempt;
1951	        }
1952	        mission_reserved_at_[mission_id] = std::chrono::steady_clock::now();
1953	        attempt.success = true;
1954	        return attempt;
1955	      };
1956	
1957	  const auto tick_plan = amr_dispatcher_core::workflow::PlanDispatchTick(tick_request);
1958	
1959	  // ---- 按序落地 step ----
1960	  std::optional<ReadyCandidate> ready;
1961	  for (const auto& step : tick_plan.steps) {
1962	    switch (step.kind) {
1963	      case amr_dispatcher_core::workflow::DispatchStep::Kind::kRejectCandidate: {
1964	        // 永久不满足 -> 该单判负（不静默改派）
1965	        RCLCPP_WARN(get_logger(), "Queued mission %s rejected by vehicle selection: %s",
1966	                    step.mission_id.c_str(), step.reason.c_str());
1967	        const auto mission_it = missions_by_id.find(step.mission_id);
1968	        if (mission_it != missions_by_id.end() && queue_->Cancel(step.mission_id)) {
1969	          RejectedQueuedMission(mission_it->second, step.reason);
1970	        }
1971	        break;
1972	      }
1973	      case amr_dispatcher_core::workflow::DispatchStep::Kind::kRecordWait:
1974	        dispatch_counters_.dispatch_deferred_total++;
1975	        dispatch_counters_.lock_contention_total++;
1976	        // 时空窗被拒是"先告警后记账"，静态锁被拒是"先记账后告警"（保持原顺序）。
1977	        if (step.denial_kind ==
1978	            amr_dispatcher_core::workflow::ReservationAttempt::DenialKind::kTimeSpace) {
