    resp->queue_size = 0;
    return;
  }
  amr_dispatcher_core::dispatcher::Mission m;
  StampMissionIdentity(m, next_sequence_, "preempt_");  // B4：id/sequence 同源
  m.order_id = req->mission_file;
  m.priority = req->priority > 100 ? req->priority : 100;
