2214	                "Dispatched mission via NavigateSequence: %s (order=%s, type=%s, prio=%d, %s->%s)",
2215	                m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
2216	                m.pickup_station.c_str(), m.dropoff_station.c_str());
2217	
2218	    if (event_pub_ && event_pub_->is_activated()) {
2219	      amr_dispatcher_interfaces::msg::MissionEvent msg;
2220	      msg.stamp = now();
2221	      msg.mission_id = m.id;
2222	      msg.order_id = m.order_id;
2223	      msg.event = "active";
2224	      msg.from_state = "PENDING";
2225	      msg.to_state = "ACTIVE";
2226	      msg.reason = "dispatched by scheduler";
2227	      event_pub_->publish(msg);
2228	    }
2229	    return;
2230	  }
2231	
2232	  nav_msgs::msg::Path path_msg;
2233	  path_msg.header.stamp = now();
2234	  path_msg.header.frame_id = "map";
2235	  path_msg.poses.reserve(waypoints.size());
2236	  for (const auto& wp : waypoints) {
2237	    geometry_msgs::msg::PoseStamped ps;
2238	    ps.header = path_msg.header;
2239	    ps.pose.position.x = wp.x;
2240	    ps.pose.position.y = wp.y;
2241	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
2242	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
2243	    path_msg.poses.push_back(ps);
2244	  }
2245	  // 执行后端分离（评审 P0.1）：VDA 5050 车自带控制器，**不发本地 /plan**
2246	  //（否则外部车会同时收到一条"本地折线"与一条 MQTT order，两套运动源互相打架），
2247	  // 也不占用本地 /plan 执行槽位；其"执行中"由订单状态判定（lastNodeId 推进），
2248	  // 完成判定见 Vda5050StateCb。
2249	  if (!is_vda5050_dispatch) {
2250	    PublishPlanForVehicle(dispatch_vehicle_id, path_msg);
2251	    AssignTrackingSlot(m.id, dispatch_vehicle_id);
2252	  }
2253	  RCLCPP_INFO(get_logger(), "Dispatched mission: %s (order=%s, type=%s, prio=%d, %s->%s, %zu waypoints, vehicle=%s)",
2254	              m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
2255	              m.pickup_station.c_str(), m.dropoff_station.c_str(), waypoints.size(),
2256	              dispatch_vehicle_id.empty() ? "<unassigned>" : dispatch_vehicle_id.c_str());
2257	
2258	  // A5/A7：多车并发 —— 本单已占用一台车，但**其它车可能仍空闲**。
2259	  // 重新武装启动请求：下个 tick 若还有空闲槽位，队列中的下一单会被派给另一台车，
2260	  // 从而形成真并发（否则第二单要等第一单完成才派发，"两车同时在跑"根本无从发生）。
2261	  // 单车场景行为不变：此时唯一槽位已被本单占满，ScheduleTick 的
2262	  // HasFreeVehicleSlot() 门控会直接返回（兼容红线：单车路径逐字不变）。
2263	  ReArmQueueStartRequest();
2264	
2265	  if (event_pub_ && event_pub_->is_activated()) {
2266	    amr_dispatcher_interfaces::msg::MissionEvent msg;
2267	    msg.stamp = now();
2268	    msg.mission_id = m.id;
2269	    msg.order_id = m.order_id;
2270	    msg.event = "active";
2271	    msg.from_state = "PENDING";
2272	    msg.to_state = "ACTIVE";
2273	    msg.reason = "dispatched by scheduler";
2274	    event_pub_->publish(msg);
2275	  }
2276	}
