2286	void DispatcherNode::TrackingErrorCb(
2287	    const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
2288	  // action 模式的到达信号归 bridge 消费、结果由 NavResultCb 收口：
2289	  // dispatcher 若自行 CompleteMission 会对同一 NavigateSequence goal 发
2290	  // async_cancel_goal，把已完成 goal 打成 CANCELED（审查 I2）
2291	  if (navigation_backend_ == "action") {
2292	    return;
2293	  }
2294	  // plan 模式下必须按周期喂活 progress：path_tracker_node 以 control_rate_hz
2295	  // 持续发布 /tracking/error，若仅 arrived=true 才刷新时间戳，长距离巡航
2296	  // (>10s) 会触发 DeadlockDetector 的 active_idle_threshold 误判并取消任务
2297	  // legacy 全局 /tracking/error：只服务"没有车辆归属"的任务（单车兼容路径）。
2298	  // 多车模式下每台车的 arrived 走 TrackingErrorCbForVehicle。
2299	  const auto legacy_it = vehicle_current_mission_.find("");
2300	  if (legacy_it != vehicle_current_mission_.end()) {
2301	    mission_last_progress_[legacy_it->second] = std::chrono::steady_clock::now();
2302	  }
2303	  if (!msg->arrived || legacy_it == vehicle_current_mission_.end()) {
2304	    return;
2305	  }
2306	  const std::string finished_id = legacy_it->second;
2307	  ReleaseTrackingSlot(finished_id);
2308	  mission_last_progress_[finished_id] = std::chrono::steady_clock::now();
2309	  CompleteMission(finished_id, "arrived at goal");
2310	}
