2312	void DispatcherNode::CompleteMission(std::string mission_id_in, const std::string& reason) {
2313	  // 按值接收 mission_id：调用方可能传入 active_missions_ 里的键引用
2314	  // （如 Vda5050StateCb 的 mission_it->first），而本函数会 erase 该条目——
2315	  // 引用会随即悬空（e2e 曾复现段错误）。
2316	  const std::string mission_id = mission_id_in;
2317	  // 单车执行槽位兜底释放：plan 模式由 TrackingErrorCb 先清（幂等）、
2318	  // action 模式由 NavResultCb 收口——此处不清则槽位残留，后续任务永远无法派发（审查 C1）
2319	  ReleaseTrackingSlot(mission_id);
2320	  std::string order_id;
2321	  {
2322	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
2323	    auto it = active_missions_.find(mission_id);
2324	    if (it == active_missions_.end()) {
2325	      return;
2326	    }
2327	    order_id = it->second.order_id;
2328	    active_missions_.erase(it);
2329	  }
2330	  // ExecuteMission goal 成功收口；action 模式清在途导航 goal（result 到达前的兜底取消）
2331	  MarkStateDirty();  // 在途任务集变化
2332	  FinishExecuteGoal(mission_id, ExecuteFinish::kSucceed, reason, 0);
2333	  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
2334	  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
2335	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
2336	    if (nav_client_ && pending_nav_goal_handle_) {
2337	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
2338	    }
2339	    pending_nav_mission_id_.clear();
2340	    pending_nav_goal_handle_.reset();
2341	  }
2342	
2343	  // 结果处理走 mission_result 行为树：成功分支给资源释放与失败计数复位决策
2344	  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
2345	  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kSucceeded;
2346	  result_input.result_success = true;
2347	  result_input.result_message = reason;
2348	  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
2349	  RCLCPP_INFO(get_logger(), "Mission %s result via BT: branch=%s state=%s", mission_id.c_str(),
2350	              result_bt.branch.c_str(),
2351	              result_bt.success ? result_bt.decision.state.c_str() : "tree_failed");
2352	
2353	  // 树失败时回退旧行为（无条件释放），防树异常导致资源泄漏
2354	  if (!result_bt.success || result_bt.decision.release_all_resources) {
2355	    if (reservation_table_) {
2356	      reservation_table_->Release(mission_id);
2357	    }
2358	  }
2359	  if (result_bt.success && result_bt.decision.reset_failure_retry_count) {
2360	    mission_attempts_.erase(mission_id);
2361	    mission_last_progress_.erase(mission_id);
2362	  }
2363	  RCLCPP_INFO(get_logger(), "Mission completed: %s (%s)", mission_id.c_str(), reason.c_str());
2364	  if (event_pub_ && event_pub_->is_activated()) {
2365	    amr_dispatcher_interfaces::msg::MissionEvent msg;
2366	    msg.stamp = now();
2367	    msg.mission_id = mission_id;
2368	    msg.order_id = order_id;
2369	    msg.event = "completed";
2370	    msg.from_state = "ACTIVE";
2371	    msg.to_state = "FINISHED";
2372	    msg.reason = reason;
2373	    event_pub_->publish(msg);
2374	  }
2375	  if (event_log_) {
2376	    amr_dispatcher_core::dispatcher::MissionEvent evt;
2377	    evt.stamp = "now";
2378	    evt.mission_id = mission_id;
2379	    evt.event = "completed";
2380	    evt.message = reason;
2381	    event_log_->Append(evt);
2382	  }
2383	  ReArmQueueStartRequest();  // 队列非空时重新武装 runtime 树的启动请求
2384	}
