2386	void DispatcherNode::FailMission(std::string mission_id_in, const std::string& reason) {
2387	  // 同 CompleteMission：按值接收，避免调用方传入的 map 键引用在 erase 后悬空
2388	  const std::string mission_id = mission_id_in;
2389	  std::string order_id;
2390	  amr_dispatcher_core::dispatcher::Mission mission_copy;
2391	  {
2392	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
2393	    auto it = active_missions_.find(mission_id);
2394	    if (it == active_missions_.end()) {
2395	      return;
2396	    }
2397	    order_id = it->second.order_id;
2398	    mission_copy = it->second;
2399	    active_missions_.erase(it);
2400	  }
2401	  MarkStateDirty();  // 在途任务集变化
2402	  // ExecuteMission goal 失败收口（error_code=1）；action 模式取消在途导航 goal
2403	  FinishExecuteGoal(mission_id, ExecuteFinish::kAbort, reason, 1);
2404	  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
2405	  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
2406	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
2407	    if (nav_client_ && pending_nav_goal_handle_) {
2408	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
2409	    }
2410	    pending_nav_mission_id_.clear();
2411	    pending_nav_goal_handle_.reset();
2412	  }
2413	
2414	  // 失败结果先经 mission_result 行为树分类：资源释放决策 + 失败处理标记
2415	  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
2416	  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kFailed;
2417	  result_input.result_success = false;
2418	  result_input.result_message = reason;
2419	  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
2420	
2421	  if (!result_bt.success || result_bt.decision.release_all_resources) {
2422	    if (reservation_table_) {
2423	      reservation_table_->Release(mission_id);
2424	    }
2425	  }
2426	  if (IsMissionTracked(mission_id)) {
2427	    // 发布空路径让 path_tracker 停下
2428	    PublishStopPathForMission(mission_id);
2429	    ReleaseTrackingSlot(mission_id);
2430	  }
2431	  RCLCPP_WARN(get_logger(), "Mission failed: %s (%s)", mission_id.c_str(), reason.c_str());
2432	  if (event_pub_ && event_pub_->is_activated()) {
2433	    amr_dispatcher_interfaces::msg::MissionEvent msg;
2434	    msg.stamp = now();
2435	    msg.mission_id = mission_id;
2436	    msg.order_id = order_id;
2437	    msg.event = "failed";
2438	    msg.from_state = "ACTIVE";
2439	    msg.to_state = "FAILED";
2440	    msg.reason = reason;
2441	    event_pub_->publish(msg);
2442	  }
2443	
2444	  // 恢复策略走 mission_recovery 行为树：retry / dock / manual 三级决策
2445	  const bool handle_failure = !result_bt.success || result_bt.decision.handle_failure;
2446	  std::string recovery_action = "none";
2447	  std::string recovery_message;
2448	  if (handle_failure && queue_) {
2449	    amr_dispatcher_bt::MissionRecoveryBehaviorTreeInput rec_input;
2450	    rec_input.retry_count = mission_attempts_[mission_id];
2451	    rec_input.is_dock_mission = mission_copy.type == "charge";
2452	    rec_input.mission_id = mission_id;
2453	    rec_input.failure_message =
2454	        (result_bt.success && !result_bt.decision.failure_message.empty())
2455	            ? result_bt.decision.failure_message
2456	            : reason;
2457	    rec_input.recovery_priority = mission_copy.priority;
2458	    rec_input.next_queue_sequence = next_sequence_;
2459	    const auto rec_bt = amr_dispatcher_bt::TickMissionRecoveryBehaviorTree(rec_input);
2460	    recovery_action = rec_bt.decision.action;
2461	    recovery_message = rec_bt.decision.message;
2462	    RCLCPP_INFO(get_logger(), "Recovery via BT: branch=%s action=%s recoverable=%d (%s)",
2463	                rec_bt.branch.c_str(), rec_bt.decision.action.c_str(),
2464	                rec_bt.decision.recoverable ? 1 : 0, rec_bt.decision.message.c_str());
2465	
2466	    if (rec_bt.success && rec_bt.decision.action == "retry") {
2467	      auto retry = mission_copy;
2468	      retry.attempt += 1;
2469	      auto push = queue_->Push(retry);
2470	      if (push.accepted) {
2471	        mission_attempts_[mission_id] = rec_input.retry_count + 1;
2472	        queue_start_requested_ = true;
2473	      } else {
2474	        recovery_action = "manual";
2475	        recovery_message = "retry re-enqueue rejected: " + push.message;
2476	      }
2477	    } else if (rec_bt.success && rec_bt.decision.action == "dock") {
2478	      // 回坞：入队一条到充电站点的 charge 任务；站点缺失则降级为仅记录
2479	      const auto& catalog = catalog_reloader_ ? catalog_reloader_->catalog()
2480	                                              : amr_dispatcher_core::catalog::StationCatalog{};
2481	      const auto* dock_st = amr_dispatcher_core::catalog::FindStation(catalog, recovery_dock_station_);
2482	      if (dock_st) {
2483	        amr_dispatcher_core::dispatcher::Mission dock_m;
2484	        StampMissionIdentity(dock_m, next_sequence_);  // B4：id/sequence 同源
2485	        dock_m.order_id = "dock_" + mission_id;
2486	        dock_m.type = "charge";
2487	        dock_m.dropoff_station = recovery_dock_station_;
2488	        dock_m.priority = mission_copy.priority;
2489	        auto push = queue_->Push(dock_m);
2490	        if (push.accepted) {
2491	          queue_start_requested_ = true;
2492	        } else {
2493	          recovery_action = "manual";
2494	          recovery_message = "dock enqueue rejected: " + push.message;
2495	        }
2496	      } else {
2497	        recovery_action = "manual";
2498	        recovery_message = "dock station not found: " + recovery_dock_station_;
2499	      }
2500	    }
2501	
2502	    if (event_pub_ && event_pub_->is_activated()) {
2503	      amr_dispatcher_interfaces::msg::MissionEvent msg;
2504	      msg.stamp = now();
2505	      msg.mission_id = mission_id;
2506	      msg.order_id = order_id;
2507	      msg.event = "recovery";
2508	      msg.from_state = "FAILED";
2509	      msg.to_state = recovery_action == "manual" ? "MANUAL_INTERVENTION" : "RECOVERING";
2510	      msg.reason = recovery_action + ": " + recovery_message;
2511	      event_pub_->publish(msg);
2512	    }
2513	    if (event_log_) {
2514	      amr_dispatcher_core::dispatcher::MissionEvent evt;
2515	      evt.stamp = "now";
2516	      evt.mission_id = mission_id;
2517	      evt.event = "recovery";
2518	      evt.message = recovery_action + ": " + recovery_message;
2519	      event_log_->Append(evt);
2520	    }
2521	  }
2522	  ReArmQueueStartRequest();
2523	}
