2525	amr_dispatcher_core::dispatcher::DeadlockSnapshot DispatcherNode::BuildDeadlockSnapshot() {
2526	  // 组包逻辑下沉 core 纯函数（AssembleDeadlockSnapshot），这里只做三件事：
2527	  // 采集容器 -> 调纯函数 -> 按返回的 id 清单清扫幽灵等待者。
2528	  amr_dispatcher_core::dispatcher::DeadlockSnapshotSources sources;
2529	  sources.active_missions = active_missions_;
2530	  sources.last_progress = mission_last_progress_;
2531	  sources.reservation_acquired_at = mission_reserved_at_;
2532	  sources.pending_wait = pending_wait_;
2533	  sources.in_flight_pending_wait = in_flight_pending_wait_;
2534	  if (reservation_table_) {
2535	    sources.reserved_resources = reservation_table_->Snapshot();
2536	  }
2537	  // 等待记录只对仍在排队的任务有效：被批量取消/离场的等待者不进 waiting_for
2538	  //（防 WFG 残留幽灵等待者；派发成功/终态路径已即时遗忘，此处兜底清扫）。
2539	  // 队列尚未建立时不做判定（与原实现 queue_ == nullptr 分支一致）。
2540	  sources.filter_stale_waiters = (queue_ != nullptr);
2541	  if (queue_) {
2542	    for (const auto& queued : queue_->SnapshotForPersistence()) {
2543	      sources.queued_mission_ids.insert(queued.id);
2544	    }
2545	  }
2546	
2547	  auto assembly = amr_dispatcher_core::dispatcher::AssembleDeadlockSnapshot(sources);
2548	  for (const auto& stale_id : assembly.stale_wait_mission_ids) {
2549	    pending_wait_.erase(stale_id);
2550	  }
2551	  return std::move(assembly.snapshot);
2552	}
2553	
2554	void DispatcherNode::DeadlockTick() {
2555	  if (!deadlock_detector_ || !recovery_policy_) {
2556	    return;
2557	  }
2558	
2559	  // 与 DetectTrafficDeadlockCb 统一锁约定：BuildDeadlockSnapshot 读 active_missions_，
2560	  // 当前虽是单线程 spin（无并发语义变化），但约定不统一迟早会在切
2561	  // MultiThreadedExecutor 时变成数据竞争。
2562	  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
2563	  {
2564	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
2565	    snap = BuildDeadlockSnapshot();
2566	  }
2567	
2568	  const auto findings = deadlock_detector_->Detect(snap);
2569	  deadlock_flag_ = !findings.empty();
2570	
2571	  // 拓扑状态投影的死锁输入：存各 finding 的环路径，无死锁时清空
2572	  last_deadlock_findings_.clear();
2573	  for (const auto& finding : findings) {
2574	    if (!finding.cycle_path.empty()) {
2575	      last_deadlock_findings_.push_back(finding.cycle_path);
2576	    }
2577	  }
2578	
2579	  if (deadlock_flag_) {
2580	    RCLCPP_WARN(get_logger(), "Deadlock findings count: %zu", findings.size());
2581	
2582	    // Phase 7 (P1/P2): 优先对有向死锁环尝试执行安全拓扑绕行破环
2583	    bool cycle_resolved_by_reroute = false;
2584	    for (const auto& finding : findings) {
2585	      if (finding.kind == amr_dispatcher_core::dispatcher::DeadlockKind::kMutualBlock &&
2586	          !finding.cycle_path.empty() && catalog_reloader_) {
2587	        amr_dispatcher_core::workflow::DeadlockRecoveryRequest recovery_req;
2588	        recovery_req.catalog = &catalog_reloader_->catalog();
2589	        recovery_req.cycle_mission_ids = finding.mission_ids;
2590	
2591	        // 提取死锁环中涉及的边锁 (奇数位资源为锁名)
2592	        for (std::size_t i = 1; i < finding.cycle_path.size(); i += 2) {
2593	          if (finding.cycle_path[i].rfind("route_edge:", 0) == 0) {
2594	            recovery_req.cycle_blocked_edges.insert(finding.cycle_path[i]);
2595	          }
2596	        }
2597	
2598	        // 构建各涉案在途任务的候选状态
2599	        for (const auto& mid : finding.mission_ids) {
2600	          auto it = active_missions_.find(mid);
2601	          if (it == active_missions_.end()) {
2602	            continue;
2603	          }
2604	          amr_dispatcher_core::workflow::DeadlockRecoveryCandidate cand;
2605	          cand.mission_id = mid;
2606	          cand.priority = it->second.priority;
2607	          cand.destination_node = it->second.dropoff_station;
2608	
2609	          // 反查当前绑定的车辆与最近停靠的安全节点
2610	          auto track_it = mission_tracking_vehicle_.find(mid);
2611	          if (track_it != mission_tracking_vehicle_.end()) {
2612	            cand.vehicle_id = track_it->second;
2613	          } else {
2614	            auto vda_it = vda5050_mission_vehicle_.find(mid);
2615	            if (vda_it != vda5050_mission_vehicle_.end()) {
2616	              cand.vehicle_id = vda_it->second;
2617	            }
2618	          }
2619	
2620	          auto safe_node_it = vehicle_safe_nodes_.find(cand.vehicle_id);
2621	          if (safe_node_it != vehicle_safe_nodes_.end() && !safe_node_it->second.empty()) {
2622	            cand.current_safe_node = safe_node_it->second;
2623	          } else {
2624	            cand.current_safe_node = it->second.pickup_station;
2625	          }
2626	
2627	          auto path_it = mission_route_paths_.find(mid);
2628	          if (path_it != mission_route_paths_.end()) {
2629	            cand.full_original_path = path_it->second;
2630	          }
2631	          if (reservation_table_) {
2632	            for (const auto& [res_id, owner] : reservation_table_->Snapshot()) {
2633	              if (owner == mid) {
2634	                cand.current_held_locks.push_back(res_id);
2635	              }
2636	            }
2637	          }
2638	          recovery_req.candidates.push_back(std::move(cand));
2639	        }
2640	
2641	        const auto recovery_dec =
2642	            amr_dispatcher_core::workflow::PlanDeadlockRecovery(recovery_req);
2643	
2644	        if (recovery_dec.action ==
2645	            amr_dispatcher_core::workflow::DeadlockRecoveryDecision::Action::kRerouteMission) {
2646	          const auto& reroute = recovery_dec.reroute_decision;
2647	          const std::string& mid = recovery_dec.selected_mission_id;
2648	          RCLCPP_WARN(get_logger(),
2649	                      "Phase 7 Deadlock recovery: rerouting mission %s to break cycle",
2650	                      mid.c_str());
2651	
2652	          // 【两阶段置换步骤 1】先对新路线所需锁进行原子预留
2653	          bool reserve_ok = true;
2654	          if (!reroute.new_required_locks.empty() && reservation_table_) {
2655	            auto res = reservation_table_->Reserve(mid, reroute.new_required_locks);
2656	            reserve_ok = res.success;
2657	          }
2658	
2659	          if (reserve_ok) {
2660	            // 【两阶段置换步骤 2】预留成功：释放旧路线不再需要的废弃锁
2661	            if (!reroute.obsolete_locks.empty() && reservation_table_) {
2662	              reservation_table_->ReleaseResources(mid, reroute.obsolete_locks);
2663	            }
2664	
2665	            // 更新任务路线并下发新计划
2666	            mission_route_paths_[mid] = reroute.full_updated_path;
2667	            in_flight_pending_wait_.erase(mid);
2668	
2669	            auto track_it = mission_tracking_vehicle_.find(mid);
2670	            if (track_it != mission_tracking_vehicle_.end() && planner_) {
2671	              const std::string& vid = track_it->second;
2672	              auto pose_it = vehicle_poses_.find(vid);
2673	              amr_dispatcher_core::Pose2D start_pose{
2674	                  (pose_it != vehicle_poses_.end() && pose_it->second.has_odom)
2675	                      ? pose_it->second.pose.x
2676	                      : current_pose_.x,
2677	                  (pose_it != vehicle_poses_.end() && pose_it->second.has_odom)
2678	                      ? pose_it->second.pose.y
2679	                      : current_pose_.y,
2680	                  (pose_it != vehicle_poses_.end() && pose_it->second.has_odom)
2681	                      ? pose_it->second.pose.yaw
2682	                      : current_pose_.yaw};
2683	              amr_dispatcher_core::Pose2D goal_pose{0.0, 0.0, 0.0};
2684	              const auto* dest_station =
2685	                  amr_dispatcher_core::catalog::FindStation(
2686	                      catalog_reloader_->catalog(), active_missions_[mid].dropoff_station);
2687	              if (dest_station) {
2688	                goal_pose.x = dest_station->x;
2689	                goal_pose.y = dest_station->y;
2690	                goal_pose.theta = dest_station->yaw;
2691	              }
2692	              const auto waypoints = planner_->Plan(start_pose, goal_pose);
2693	              nav_msgs::msg::Path path_msg;
2694	              path_msg.header.stamp = now();
2695	              path_msg.header.frame_id = "map";
2696	              for (const auto& wp : waypoints) {
2697	                geometry_msgs::msg::PoseStamped ps;
2698	                ps.header = path_msg.header;
2699	                ps.pose.position.x = wp.x;
2700	                ps.pose.position.y = wp.y;
2701	                ps.pose.orientation.z = std::sin(wp.theta / 2.0);
2702	                ps.pose.orientation.w = std::cos(wp.theta / 2.0);
2703	                path_msg.poses.push_back(ps);
2704	              }
2705	              PublishPlanForVehicle(vid, path_msg);
2706	            } else {
2707	              auto vda_it = vda5050_mission_vehicle_.find(mid);
2708	              if (vda_it != vda5050_mission_vehicle_.end()) {
2709	                PublishVda5050Order(mid, vda_it->second);
2710	              }
2711	            }
2712	
2713	            if (event_pub_ && event_pub_->is_activated()) {
2714	              amr_dispatcher_interfaces::msg::MissionEvent msg;
2715	              msg.stamp = now();
2716	              msg.mission_id = mid;
2717	              msg.order_id = active_missions_[mid].order_id;
2718	              msg.event = "rerouted";
2719	              msg.to_state = "RUNNING";
2720	              msg.reason = recovery_dec.message;
2721	              event_pub_->publish(msg);
2722	            }
2723	            cycle_resolved_by_reroute = true;
2724	            break;
2725	          } else {
2726	            RCLCPP_WARN(get_logger(),
2727	                        "Reroute reservation failed for mission %s; retaining original locks",
2728	                        mid.c_str());
2729	          }
2730	        }
2731	      }
2732	    }
2733	
2734	    if (cycle_resolved_by_reroute) {
2735	      return;  // 成功通过拓扑重规划破环，无需走降级取消/暂停
2736	    }
2737	
2738	    auto actions = recovery_policy_->Decide(
2739	        findings, [this](const std::string& mid) {
2740	          auto it = mission_attempts_.find(mid);
2741	          return it != mission_attempts_.end() ? it->second : 0;
2742	        });
2743	
2744	    for (const auto& act : actions) {
2745	      RCLCPP_WARN(get_logger(), "Recovery action on %s: reason=%s",
2746	                  act.mission_id.c_str(), act.reason.c_str());
2747	      if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kPause) {
2748	        queue_->PauseOrder(act.mission_id);
2749	      } else if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kCancel) {
2750	        // 取消也走结果树：canceled 分支给资源释放决策，同时补发可观测事件
2751	        std::string canceled_order_id;
2752	        auto cancel_it = active_missions_.find(act.mission_id);
2753	        if (cancel_it != active_missions_.end()) {
2754	          canceled_order_id = cancel_it->second.order_id;
2755	        }
2756	        amr_dispatcher_core::workflow::MissionResultWorkflowInput cancel_input;
2757	        cancel_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kCanceled;
2758	        cancel_input.result_message = act.reason;
2759	        const auto cancel_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(cancel_input);
2760	        active_missions_.erase(act.mission_id);
2761	        if (!cancel_bt.success || cancel_bt.decision.release_all_resources) {
2762	          if (reservation_table_) {
2763	            reservation_table_->Release(act.mission_id);
2764	          }
2765	        }
2766	        // 死锁恢复取消的级联：清在途 NavigateSequence goal + 终结 ExecuteMission goal
2767	        if (navigation_backend_ == "action" && pending_nav_mission_id_ == act.mission_id) {
2768	          if (nav_client_ && pending_nav_goal_handle_) {
2769	            nav_client_->async_cancel_goal(pending_nav_goal_handle_);
2770	          }
2771	          pending_nav_mission_id_.clear();
2772	          pending_nav_goal_handle_.reset();
2773	        }
2774	        FinishExecuteGoal(act.mission_id, ExecuteFinish::kAbort, act.reason, 1);
2775	        mission_dispatch_time_.erase(act.mission_id);  // plan 模式无 handle 时的派发时刻遗忘
2776	        ForgetMissionDispatchState(act.mission_id);    // 路由锁记账/等待记录/派发起点遗忘
2777	        // 死锁恢复取消到正在跟踪 /plan 的任务时，必须释放跟踪槽位并停车，
2778	        // 否则执行槽位悬挂导致后续任务永远无法下发。
2779	        if (IsMissionTracked(act.mission_id)) {
2780	          ReleaseTrackingSlot(act.mission_id);
2781	          PublishStopPathForMission(act.mission_id);
2782	        }
2783	        if (event_pub_ && event_pub_->is_activated()) {
2784	          amr_dispatcher_interfaces::msg::MissionEvent msg;
2785	          msg.stamp = now();
2786	          msg.mission_id = act.mission_id;
2787	          msg.order_id = canceled_order_id;
2788	          msg.event = "canceled";
2789	          msg.to_state = "CANCELED";
2790	          msg.reason = act.reason;
2791	          event_pub_->publish(msg);
2792	        }
2793	        RCLCPP_WARN(get_logger(), "Deadlock cancel via BT: branch=%s state=%s reason=%s",
2794	                    cancel_bt.branch.c_str(),
2795	                    cancel_bt.success ? cancel_bt.decision.state.c_str() : "tree_failed",
2796	                    act.reason.c_str());
2797	        ReArmQueueStartRequest();
2798	      } else if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kRetry) {
2799	        // B8：写 map 前先确认任务仍在册（active 或排队中）——
2800	        // 死锁恢复决策基于快照延迟生成，目标可能已终态/被操作员移除，
2801	        // 盲区写 map 会把幽灵 mission_id 驻留在 attempts/last_progress 里。
2802	        const bool mission_known =
2803	            active_missions_.count(act.mission_id) > 0 ||
2804	            (queue_ && queue_->Contains(act.mission_id));
2805	        if (mission_known) {
2806	          mission_attempts_[act.mission_id]++;
2807	          mission_last_progress_[act.mission_id] = std::chrono::steady_clock::now();
2808	        } else {
2809	          RCLCPP_INFO(get_logger(),
2810	                      "Deadlock kRetry skipped for unknown mission %s (no longer active/queued)",
2811	                      act.mission_id.c_str());
2812	        }
2813	      }
2814	    }
2815	  }
2816	}
