2818	bool DispatcherNode::HasPendingChargeMission(const std::string& vehicle_id) const {
2819	  if (vehicle_id.empty() || !queue_) {
2820	    return false;
2821	  }
2822	  for (const auto& queued : queue_->SnapshotForPersistence()) {
2823	    if (queued.type == "charge" && queued.assigned_vehicle_id == vehicle_id) {
2824	      return true;
2825	    }
2826	  }
2827	  for (const auto& [_, mission] : active_missions_) {
2828	    if (mission.type == "charge" && mission.assigned_vehicle_id == vehicle_id) {
2829	      return true;
2830	    }
2831	  }
2832	  return false;
2833	}
