2835	void DispatcherNode::PlanAutoChargingTick() {
2836	  if (!auto_charging_enabled_ || !queue_ || auto_charging_station_.empty()) {
2837	    return;
2838	  }
2839	  if (catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
2840	    return;  // 目录未加载：无法确认充电站存在，不猜
2841	  }
2842	  const auto& catalog = catalog_reloader_->catalog();
2843	  const bool charger_known =
2844	      amr_dispatcher_core::catalog::FindStation(catalog, auto_charging_station_) != nullptr;
2845	
2846	  // 拷贝一份车辆清单再遍历：插单会改队列，但不会改 vehicle_states_
2847	  for (const auto& [vehicle_id, state] : vehicle_states_) {
2848	    amr_dispatcher_core::workflow::AutoChargingRequest request;
2849	    request.enabled = true;
2850	    request.vehicle_id = vehicle_id;
2851	    request.online = state.online;
2852	    request.busy = state.busy;
2853	    request.quarantined = state.quarantined;
2854	    request.battery_percent = state.battery_percent;
2855	    // VDA 5050 车从未收到 state 时电量是默认值 100：按"未知"处理，绝不当作满电
2856	    // 去抑制充电，也绝不当作空电去误叫车（PlanAutoCharging 对未知只回 kSkip）。
2857	    request.battery_known =
2858	        state.state_time != std::chrono::steady_clock::time_point{};
2859	    request.has_pending_charge_mission = HasPendingChargeMission(vehicle_id);
2860	    request.charger_station_id = auto_charging_station_;
2861	    request.charger_station_known = charger_known;
2862	    request.opportunity_threshold_percent = auto_charging_opportunity_threshold_percent_;
2863	    request.critical_threshold_percent = auto_charging_critical_threshold_percent_;
2864	    request.opportunity_priority = auto_charging_opportunity_priority_;
2865	    request.critical_priority = auto_charging_critical_priority_;
2866	
2867	    const auto decision = amr_dispatcher_core::workflow::PlanAutoCharging(request);
2868	    if (decision.kind != amr_dispatcher_core::workflow::AutoChargingDecision::Kind::kQueueCharge) {
2869	      continue;
2870	    }
2871	    amr_dispatcher_core::dispatcher::Mission mission;
2872	    StampMissionIdentity(mission, next_sequence_, "charge_");
2873	    mission.order_id = "charge_" + vehicle_id;
2874	    mission.type = "charge";
2875	    mission.dropoff_station = decision.charger_station_id;
2876	    // 显式绑定到这台车：充电是"这台车的事"，不能被选车策略分给别人
2877	    mission.assigned_vehicle_id = vehicle_id;
2878	    mission.priority = decision.priority;
2879	    auto push = queue_->Push(mission);
2880	    if (!push.accepted) {
2881	      RCLCPP_WARN(get_logger(), "Auto charging enqueue rejected for %s: %s",
2882	                  vehicle_id.c_str(), push.message.c_str());
2883	      continue;
2884	    }
2885	    queue_start_requested_ = true;
2886	    MarkStateDirty();
2887	    RCLCPP_INFO(get_logger(),
2888	                "Auto charging queued: %s -> %s (battery %.1f%%, %s, priority %d)",
2889	                vehicle_id.c_str(), decision.charger_station_id.c_str(),
2890	                state.battery_percent, decision.reason.c_str(), decision.priority);
2891	    if (event_pub_ && event_pub_->is_activated()) {
2892	      amr_dispatcher_interfaces::msg::MissionEvent msg;
2893	      msg.stamp = now();
2894	      msg.mission_id = mission.id;
2895	      msg.order_id = mission.order_id;
2896	      msg.event = "charge_queued";
2897	      msg.from_state = "PENDING";
2898	      msg.to_state = "PENDING";
2899	      msg.reason = decision.reason;
2900	      event_pub_->publish(msg);
2901	    }
2902	    if (event_log_) {
2903	      amr_dispatcher_core::dispatcher::MissionEvent evt;
2904	      evt.stamp = "now";
2905	      evt.mission_id = mission.id;
2906	      evt.event = "charge_queued";
2907	      evt.message = decision.reason;
2908	      event_log_->Append(evt);
2909	    }
2910	  }
2911	}
