2913	void DispatcherNode::ReArmQueueStartRequest() {
2914	  // 结果/取消/恢复后重新武装 runtime 行为树的启动请求：
2915	  // 队列非空则置位（auto_start_queue 语义），队列清空则复位。
2916	  const auto decision = amr_dispatcher_core::workflow::PlanMissionPostResultQueue(
2917	      amr_dispatcher_core::workflow::MissionPostResultQueueRequest{
2918	          /*existing_queue_start_requested=*/queue_start_requested_,
2919	          /*auto_start_queue=*/true,
2920	          /*queue_running=*/true,
2921	          /*mission_queue_empty=*/queue_ == nullptr || queue_->empty()});
2922	  queue_start_requested_ = decision.queue_start_requested;
