2925	// ---- Task 5：VDA 5050 逐段解锁与断链守卫（Spec §5.2/§5.3）----
2926	
2927	// ---- P0.6 / A4：per-vehicle 话题与 TF 隔离 ----
2928	
2929	void DispatcherNode::SetupVehicleTopics(const std::string& vehicles_param) {
2930	  vehicle_ids_.clear();
2931	  vehicle_plan_pubs_.clear();
2932	  vehicle_odom_subs_.clear();
2933	  vehicle_tracking_error_subs_.clear();
2934	  vehicle_poses_.clear();
2935	
2936	  for (const auto& vehicle_id : SplitVehicleIds(vehicles_param)) {
2937	    if (!IsValidVehicleId(vehicle_id)) {
2938	      RCLCPP_WARN(get_logger(),
2939	                  "P0.6: invalid vehicle id '%s' (must match [A-Za-z_][A-Za-z0-9_]*) — skipped",
2940	                  vehicle_id.c_str());
2941	      continue;
2942	    }
2943	    vehicle_ids_.push_back(vehicle_id);
2944	    // /plan/{vid} 发布端：每车一份，避免多车互相覆盖路径。
2945	    vehicle_plan_pubs_[vehicle_id] =
2946	        create_publisher<nav_msgs::msg::Path>(ResolveVehicleTopic("", "/plan", vehicle_id), 1);
2947	    // /odom/{vid} 订阅：只更新 vehicle_poses_，不动 legacy 的 current_pose_/has_odom_。
2948	    vehicle_odom_subs_[vehicle_id] = create_subscription<nav_msgs::msg::Odometry>(
2949	        ResolveVehicleTopic("", "/odom", vehicle_id), 10,
2950	        [this, vehicle_id](const nav_msgs::msg::Odometry::SharedPtr msg) {
2951	          OdomCbForVehicle(vehicle_id, msg);
2952	        });
2953	    // /tracking/error/{vid} 订阅：到达信号按车隔离（A5 收口点）。
2954	    vehicle_tracking_error_subs_[vehicle_id] =
2955	        create_subscription<amr_dispatcher_interfaces::msg::TrackingError>(
2956	            ResolveVehicleTopic("", "/tracking/error", vehicle_id), 10,
2957	            [this, vehicle_id](const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
2958	              TrackingErrorCbForVehicle(vehicle_id, msg);
2959	            });
2960	  }
2961	  if (vehicle_ids_.empty()) {
2962	    return;  // 单车兼容模式：零行为变化
2963	  }
2964	  std::string joined;
2965	  for (const auto& id : vehicle_ids_) {
2966	    if (!joined.empty()) joined += ", ";
2967	    joined += id;
2968	  }
2969	  RCLCPP_INFO(get_logger(),
2970	              "P0.6: per-vehicle topics enabled for {%s} (/plan/{vid}, /odom/{vid}, "
2971	              "/tracking/error/{vid})",
2972	              joined.c_str());
2973	}
