3004	void DispatcherNode::TrackingErrorCbForVehicle(
3005	    const std::string& vehicle_id, const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
3006	  // A5 收口点：把 arrived 信号路由到"该车正在执行的任务"并完成它。
3007	  // 进度心跳（arrived=false）同样要喂：否则长距离巡航会被死锁检测判为 idle 取消。
3008	  const auto it = vehicle_current_mission_.find(vehicle_id);
3009	  if (it == vehicle_current_mission_.end()) {
3010	    return;  // 该车当前没有在途任务：幂等忽略（重复 arrived / 迟到的信号）
3011	  }
3012	  const std::string mission_id = it->second;
3013	  mission_last_progress_[mission_id] = std::chrono::steady_clock::now();
3014	  if (!msg->arrived) {
3015	    return;
3016	  }
3017	  ReleaseTrackingSlot(mission_id);
3018	  mission_last_progress_[mission_id] = std::chrono::steady_clock::now();
3019	  RCLCPP_INFO(get_logger(), "P0.6: vehicle %s arrived -> completing mission %s",
3020	              vehicle_id.c_str(), mission_id.c_str());
3021	  CompleteMission(mission_id, "arrived at goal");
3022	}
3023	
3024	std::string DispatcherNode::ResolveDispatchVehicleId(
3025	    const amr_dispatcher_core::dispatcher::Mission& mission) {
3026	  // A6：显式指定优先（必须在受管清单内），否则由选车策略决定。
3027	  // 返回空串 = 未选到车（调度侧已据三态结果处理留队/暂停/拒绝）。
3028	  const auto decision = SelectVehicleForMission(mission);
3029	  // 三态 -> 动作的映射与排队派发链共用同一纯函数（A7）
3030	  const auto dispatch_decision = DecideAssignmentDispatch(decision);
3031	  switch (dispatch_decision.action) {
3032	    case AssignmentDispatchAction::kDispatch:
3033	      return decision.vehicle_id;
3034	    case AssignmentDispatchAction::kStayQueued:
3035	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3036	                           "Mission %s: vehicle assignment deferred (%s)",
3037	                           mission.id.c_str(), dispatch_decision.reason.c_str());
3038	      return "";
3039	    case AssignmentDispatchAction::kPauseAutoAssignment:
3040	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3041	                           "Mission %s: vehicle state indeterminate (%s) — auto assignment paused",
3042	                           mission.id.c_str(), dispatch_decision.reason.c_str());
3043	      return "";
3044	    case AssignmentDispatchAction::kReject:
3045	      RCLCPP_WARN(get_logger(), "Mission %s: vehicle assignment rejected: %s",
3046	                  mission.id.c_str(), dispatch_decision.reason.c_str());
3047	      return "";
3048	  }
3049	  return "";
3050	}
