3052	// ---- B3：时空窗交通协调 ----
3053	
3054	bool DispatcherNode::ReserveTimeSpaceForMission(
3055	    const std::string& mission_id, const std::vector<std::string>& path_node_ids,
3056	    std::string* message) {
3057	  if (!UseTimeSpaceMode()) {
3058	    if (message != nullptr) *message = "traffic_mode is not time_space";
3059	    return false;
3060	  }
3061	  if (path_node_ids.size() < 2) {
3062	    if (message != nullptr) *message = "path needs at least 2 nodes";
3063	    return false;
3064	  }
3065	  if (catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
3066	    if (message != nullptr) *message = "station catalog not loaded";
3067	    return false;
3068	  }
3069	  const auto& catalog = catalog_reloader_->catalog();
3070	
3071	  // 逐段长度（米）：取目录里该段边的 distance_m
3072	  std::vector<double> segment_lengths;
3073	  segment_lengths.reserve(path_node_ids.size() - 1);
3074	  for (std::size_t i = 0; i + 1 < path_node_ids.size(); ++i) {
3075	    double length = 0.0;
3076	    bool found = false;
3077	    for (const auto& edge : catalog.edges) {
3078	      const bool forward = edge.from == path_node_ids[i] && edge.to == path_node_ids[i + 1];
3079	      const bool reverse = edge.bidirectional && edge.to == path_node_ids[i] &&
3080	                           edge.from == path_node_ids[i + 1];
3081	      if (edge.enabled && (forward || reverse)) {
3082	        length = edge.distance_m;
3083	        found = true;
3084	        break;
3085	      }
3086	    }
3087	    if (!found) {
3088	      // 目录里没有该段的几何长度 -> 无法换算时间窗（不猜）
3089	      if (message != nullptr) {
3090	        *message = "no segment length for " + path_node_ids[i] + " -> " + path_node_ids[i + 1];
3091	      }
3092	      return false;
3093	    }
3094	    segment_lengths.push_back(length);
3095	  }
3096	
3097	  amr_dispatcher_core::workflow::TimeSpaceCandidate candidate;
3098	  candidate.mission_id = mission_id;
3099	  candidate.path_node_ids = path_node_ids;
3100	  candidate.segment_lengths_m = segment_lengths;
3101	  candidate.earliest_start = std::chrono::steady_clock::now();
3102	  candidate.edge_id_builder = [](const std::string& from, const std::string& to) {
3103	    return amr_dispatcher_core::dispatcher::ResourceTable::RouteEdgeId(from, to);
3104	  };
3105	  candidate.node_id_builder = [](const std::string& node) {
3106	    return amr_dispatcher_core::dispatcher::ResourceTable::RouteNodeId(node);
3107	  };
3108	
3109	  // 规划（逐资源窗口 + 冲突后移）
3110	  const auto plan = amr_dispatcher_core::workflow::PlanTimeSpaceReservation(
3111	      candidate, time_space_occupancy_, time_space_timing_);
3112	  if (!plan.feasible) {
3113	    if (message != nullptr) *message = plan.reject_reason;
3114	    return false;
3115	  }
3116	
3117	  // 全有或全无提交：整条路径的所有资源一次性落表；失败则整体回滚。
3118	  std::vector<std::pair<std::string, amr_dispatcher_core::dispatcher::TimeInterval>> intervals;
3119	  intervals.reserve(plan.windows.size());
3120	  for (const auto& window : plan.windows) {
3121	    intervals.emplace_back(window.resource_id,
3122	                           amr_dispatcher_core::dispatcher::TimeInterval{window.enter, window.exit});
3123	  }
3124	  std::string reserve_message;
3125	  if (!reservation_table_ ||
3126	      !reservation_table_->ReserveTimeSpaceBatch(mission_id, intervals, &reserve_message)) {
3127	    if (message != nullptr) {
3128	      *message = reservation_table_ ? reserve_message : "reservation table unavailable";
3129	    }
3130	    return false;
3131	  }
3132	  amr_dispatcher_core::workflow::CommitTimeSpaceOccupancy(&time_space_occupancy_, mission_id,
3133	                                                         plan.windows);
3134	  time_space_windows_[mission_id] = plan.windows;
3135	  RCLCPP_INFO(get_logger(),
3136	              "Time-space reservation committed for mission %s: %zu resource window(s), "
3137	              "total delay %.2fs",
3138	              mission_id.c_str(), plan.windows.size(), plan.total_delay_sec);
3139	  if (message != nullptr) *message = reserve_message;
3140	  return true;
3141	}
3142	
3143	void DispatcherNode::ReleaseTimeSpaceForResources(
3144	    const std::string& mission_id, const std::vector<std::string>& resource_ids) {
3145	  if (!UseTimeSpaceMode() || resource_ids.empty()) {
3146	    return;
3147	  }
3148	  // 1) 释放预约表里的时空区间（owner 校验）
3149	  if (reservation_table_) {
3150	    reservation_table_->ReleaseTimeSpaceResources(mission_id, resource_ids);
3151	  }
3152	  // 2) 释放核心占用表里的窗口
3153	  std::vector<std::string> released;
3154	  amr_dispatcher_core::workflow::ReleaseTimeSpaceResources(&time_space_occupancy_, mission_id,
3155	                                                           resource_ids, &released);
3156	  if (!released.empty()) {
3157	    RCLCPP_INFO(get_logger(), "Time-space windows released for mission %s: %zu resource(s)",
3158	                mission_id.c_str(), released.size());
3159	  }
3160	}
