3163	
3164	void DispatcherNode::RejectedQueuedMission(
3165	    const amr_dispatcher_core::dispatcher::Mission& mission, const std::string& reason) {
3166	  // 选车永久拒绝：任务判负（不进 active_missions_，走不到 Complete/Fail 的终态清理）
3167	  dispatch_counters_.dispatch_rejected_total++;
3168	  RCLCPP_WARN(get_logger(), "Queued mission %s rejected: %s", mission.id.c_str(), reason.c_str());
3169	  if (reservation_table_) {
3170	    reservation_table_->Release(mission.id);
3171	  }
3172	  ForgetMissionDispatchState(mission.id);
3173	  FinishExecuteGoal(mission.id, ExecuteFinish::kAbort,
3174	                    "vehicle selection rejected: " + reason, 1);
3175	  if (event_pub_ && event_pub_->is_activated()) {
3176	    amr_dispatcher_interfaces::msg::MissionEvent msg;
3177	    msg.stamp = now();
3178	    msg.mission_id = mission.id;
3179	    msg.order_id = mission.order_id;
3180	    msg.event = "failed";
3181	    msg.from_state = "PENDING";
3182	    msg.to_state = "FAILED";
3183	    msg.reason = "vehicle selection rejected: " + reason;
3184	    event_pub_->publish(msg);
3185	  }
3186	  if (event_log_) {
3187	    amr_dispatcher_core::dispatcher::MissionEvent evt;
3188	    evt.stamp = "now";
3189	    evt.mission_id = mission.id;
3190	    evt.event = "failed";
3191	    evt.message = "vehicle selection rejected: " + reason;
3192	    event_log_->Append(evt);
3193	  }
3194	  ReArmQueueStartRequest();  // 该单丢弃后，队列中其余任务仍需能被派发
3195	}
