3198	void DispatcherNode::LoadFleetCatalog() {
3199	  const std::string fleet_file = get_parameter("fleet_catalog_file").as_string();
3200	  if (fleet_file.empty()) {
3201	    // 无目录：受管车 = vehicle_ids（local_sim）+ vda5050_vehicles（外部车），
3202	    // 静态字段取默认值（enabled=true、能力不限）。
3203	    vehicle_states_.clear();
3204	    for (const auto& vehicle_id : vehicle_ids_) {
3205	      amr_dispatcher_core::fleet::VehicleRuntimeState state;
3206	      state.vehicle_id = vehicle_id;
3207	      state.backend = amr_dispatcher_core::fleet::VehicleExecutionBackend::kLocalSim;
3208	      state.enabled = true;
3209	      state.online = true;
3210	      state.busy = false;
3211	      state.battery_percent = 100.0;
3212	      state.position_valid = false;
3213	      vehicle_states_[vehicle_id] = state;
3214	    }
3215	    for (const auto& vehicle_id : vda5050_vehicle_ids_) {
3216	      amr_dispatcher_core::fleet::VehicleRuntimeState state;
3217	      state.vehicle_id = vehicle_id;
3218	      state.backend = amr_dispatcher_core::fleet::VehicleExecutionBackend::kVda5050;
3219	      state.enabled = true;
3220	      state.online = true;
3221	      state.busy = false;
3222	      state.battery_percent = 100.0;
3223	      state.position_valid = false;
3224	      vehicle_states_[vehicle_id] = state;
3225	    }
3226	    return;
3227	  }
3228	  const auto catalog = amr_dispatcher_core::fleet::LoadFleetCatalog(fleet_file);
3229	  if (!catalog.has_value()) {
3230	    RCLCPP_ERROR(get_logger(),
3231	                 "Failed to load fleet catalog %s — vehicle selection falls back to the "
3232	                 "managed vehicle lists with default static fields",
3233	                 fleet_file.c_str());
3234	    return;
3235	  }
3236	  for (const auto& robot : catalog->robots) {
3237	    amr_dispatcher_core::fleet::VehicleRuntimeState state;
3238	    state.vehicle_id = robot.id;
3239	    amr_dispatcher_core::fleet::VehicleExecutionBackend backend =
3240	        amr_dispatcher_core::fleet::VehicleExecutionBackend::kLocalSim;
3241	    amr_dispatcher_core::fleet::ParseVehicleBackend(robot.backend, &backend);
3242	    state.backend = backend;
3243	    state.enabled = robot.enabled;
3244	    state.capabilities = robot.capabilities;
3245	    state.online = true;
3246	    state.busy = false;
3247	    state.battery_percent = 100.0;
3248	    state.position_valid = false;
3249	    state.current_station_id = robot.current_station_id;
3250	    vehicle_states_[robot.id] = state;
3251	  }
3252	  RCLCPP_INFO(get_logger(), "Loaded %zu vehicle(s) from fleet catalog %s",
3253	              vehicle_states_.size(), fleet_file.c_str());
3254	}
3255	
3256	void DispatcherNode::RefreshVehicleStates() {
3257	  // local_sim 车的位置来源：/odom/{vid}
3258	  for (auto& [vehicle_id, state] : vehicle_states_) {
3259	    if (state.backend != amr_dispatcher_core::fleet::VehicleExecutionBackend::kLocalSim) {
3260	      continue;
3261	    }
3262	    const auto pose_it = vehicle_poses_.find(vehicle_id);
3263	    if (pose_it == vehicle_poses_.end() || !pose_it->second.has_odom) {
3264	      state.position_valid = false;
3265	      continue;
3266	    }
3267	    state.position_x = pose_it->second.pose.x;
3268	    state.position_y = pose_it->second.pose.y;
3269	    state.position_valid = true;
3270	    state.state_time = std::chrono::steady_clock::now();
3271	    state.busy = IsVehicleBusy(vehicle_id);
3272	  }
3273	  // VDA 5050 车的位置/电量来源：/fleet/{vid}/state
3274	  for (const auto& vehicle_id : vda5050_vehicle_ids_) {
3275	    auto it = vehicle_states_.find(vehicle_id);
3276	    if (it == vehicle_states_.end()) {
3277	      continue;
3278	    }
3279	    auto& state = it->second;
3280	    const auto link_it = vda5050_link_states_.find(vehicle_id);
3281	    if (link_it == vda5050_link_states_.end()) {
3282	      continue;
3283	    }
3284	    state.online = link_it->second.online;
3285	    state.quarantined = link_it->second.quarantined;
3286	    state.busy = !vda5050_mission_vehicle_.empty() &&
3287	                 std::any_of(vda5050_mission_vehicle_.begin(), vda5050_mission_vehicle_.end(),
3288	                             [&](const auto& entry) { return entry.second == vehicle_id; });
3289	    if (link_it->second.seen_state) {
3290	      state.state_time = link_it->second.last_state_time;
3291	      state.position_valid = link_it->second.position_valid;
3292	      state.position_x = link_it->second.position_x;
3293	      state.position_y = link_it->second.position_y;
3294	      state.battery_percent = link_it->second.battery_percent;
3295	    }
3296	  }
3297	}
