3418	
3419	void DispatcherNode::SetupVda5050Links(const std::string& vehicles_param) {
3420	  // 终审 M4：reconfigure 必须先无条件清旧链路态——否则空化 vda5050_vehicle_ids
3421	  // 会残留陈旧 link 继续喂 EnforceVda5050LinkGuard 的挂起守卫（离线车永远
3422	  // 封锁全队派发，且无人工解除途径）。
3423	  vda5050_link_subs_.clear();
3424	  vda5050_link_states_.clear();
3425	  vda5050_vehicle_ids_.clear();
3426	  vda5050_order_pubs_.clear();
3427	  vda5050_next_order_update_id_.clear();
3428	  vda5050_mission_vehicle_.clear();
3429	
3430	  vda5050_state_stale_sec_ = get_parameter("vda5050_state_stale_sec").as_double();
3431	  // 订阅策略：ROS 2 无通配订阅，网关按 MQTT 发现的小车懒建 /fleet/{vid}/* 话题。
3432	  // 采用参数显式清单（逗号分隔 id）——确定性、参数为空时零行为变化，
3433	  // 且订阅先于网关懒建话题也能收到后续消息（ROS 2 订阅者不依赖话题已存在）。
3434	  std::vector<std::string> vehicle_ids;
3435	  std::size_t start = 0;
3436	  while (start <= vehicles_param.size()) {
3437	    const auto end = vehicles_param.find(',', start);
3438	    std::string token = vehicles_param.substr(
3439	        start, end == std::string::npos ? std::string::npos : end - start);
3440	    const auto first = token.find_first_not_of(" \t");
3441	    const auto last = token.find_last_not_of(" \t");
3442	    if (first != std::string::npos) {
3443	      token = token.substr(first, last - first + 1);
3444	      if (std::find(vehicle_ids.begin(), vehicle_ids.end(), token) == vehicle_ids.end()) {
3445	        vehicle_ids.push_back(token);
3446	      }
3447	    }
3448	    if (end == std::string::npos) {
3449	      break;
3450	    }
3451	    start = end + 1;
3452	  }
3453	  if (vehicle_ids.empty()) {
3454	    return;  // 未配置受管小车：逐段解锁/断链守卫整体关闭（现网行为不变）
3455	  }
3456	  for (const auto& vehicle_id : vehicle_ids) {
3457	    vda5050_link_states_.emplace(vehicle_id, amr_dispatcher_core::fleet::Vda5050LinkState{});
3458	    auto& link = vda5050_link_subs_[vehicle_id];
3459	    link.state_sub = create_subscription<std_msgs::msg::String>(
3460	        "/fleet/" + vehicle_id + "/state", rclcpp::QoS(10),
3461	        [this, vehicle_id](const std_msgs::msg::String::SharedPtr msg) {
3462	          Vda5050StateCb(vehicle_id, msg);
3463	        });
3464	    // 与网关 online 发布端 QoS 对齐（KeepLast(1) + transient_local），
3465	    // 保证 late-join 的调度端也能收到最近一次链路状态
3466	    link.online_sub = create_subscription<std_msgs::msg::Bool>(
3467	        "/fleet/" + vehicle_id + "/online",
3468	        rclcpp::QoS(rclcpp::KeepLast(1)).transient_local(),
3469	        [this, vehicle_id](const std_msgs::msg::Bool::SharedPtr msg) {
3470	          Vda5050OnlineCb(vehicle_id, msg);
3471	        });
3472	    // Task 6：订单发布端按清单一次建齐（on_activate 激活）。网关的
3473	    // send_order 订阅虽是发现车辆后懒建，ROS 2 发布端无需对端先存在；
3474	    // QoS(10) reliable 与网关订阅侧 create_subscription(..., 10, ...) 对齐。
3475	    vda5050_order_pubs_[vehicle_id] =
3476	        create_publisher<std_msgs::msg::String>("/fleet/" + vehicle_id + "/send_order", 10);
3477	    vda5050_next_order_update_id_[vehicle_id] = 0;
3478	  }
3479	  vda5050_vehicle_ids_ = vehicle_ids;  // 保序清单：round-robin 绑定与遍历用
3480	  std::string joined;
3481	  for (const auto& id : vehicle_ids) {
3482	    if (!joined.empty()) joined += ", ";
3483	    joined += id;
3484	  }
3485	  RCLCPP_INFO(get_logger(),
3486	              "Task 5: subscribed /fleet/{%s}/{state,online} for dynamic unlock "
3487	              "(stale threshold %.1fs)",
3488	              joined.c_str(), vda5050_state_stale_sec_);
3489	}
