3491	void DispatcherNode::PublishVda5050Order(const std::string& mission_id,
3492	                                        const std::string& assigned_vehicle_id) {
3493	  if (vda5050_vehicle_ids_.empty()) {
3494	    return;  // 未配置受管 VDA 5050 车辆：无订单发布（现网行为不变）
3495	  }
3496	  if (catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
3497	    RCLCPP_WARN(get_logger(),
3498	                "Mission %s: station catalog not loaded, VDA 5050 order NOT published",
3499	                mission_id.c_str());
3500	    return;
3501	  }
3502	  const auto path_it = mission_route_paths_.find(mission_id);
3503	  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
3504	    RCLCPP_WARN(get_logger(),
3505	                "Mission %s: no archived travel path, VDA 5050 order NOT published",
3506	                mission_id.c_str());
3507	    return;
3508	  }
3509	  if (!reservation_table_) {
3510	    RCLCPP_WARN(get_logger(),
3511	                "Mission %s: reservation table unavailable, VDA 5050 order NOT published",
3512	                mission_id.c_str());
3513	    return;
3514	  }
3515	  // 本单名下实际持有的锁（builder 契约：严禁传全局快照——否则他人锁会被
3516	  // 误判为已放行，向小车下发未获路权的 released=true 边，违反 Spec §5.1）
3517	  // time_space 模式下本单持有的是**时空预约**（不是静态排他锁），
3518	  // 必须从时空预约表读，否则整单资源都会被判为"未获路权" -> released=false
3519	  // -> 小车在起点原地制动（observed: mock 车收到 released=[False] 的订单后不动）。
3520	  std::unordered_set<std::string> held_locks;
3521	  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
3522	    if (owner == mission_id) {
3523	      held_locks.insert(resource_id);
3524	    }
3525	  }
3526	  for (const auto& resource_id : reservation_table_->TimeSpaceResourcesOf(mission_id)) {
3527	    held_locks.insert(resource_id);
3528	  }
3529	  // 车辆绑定：优先用选车决策给出的承接车辆（A6）；为空或不在受管清单内时
3530	  // 回落到保序清单上的 round-robin（单车配置下结果恒定，与改动前一致）。
3531	  // 判定与游标推进下沉 core 纯函数（Vda5050VehicleBindingTest 覆盖环绕/跳号）。
3532	  amr_dispatcher_core::fleet::Vda5050VehicleBindingRequest binding_req;
3533	  binding_req.assigned_vehicle_id = assigned_vehicle_id;
3534	  binding_req.managed_vehicle_ids = &vda5050_vehicle_ids_;
3535	  binding_req.round_robin_cursor = &vda5050_rr_cursor_;
3536	  const std::string vehicle_id =
3537	      amr_dispatcher_core::fleet::BindVda5050Vehicle(binding_req).vehicle_id;
3538	  const std::uint32_t update_id = vda5050_next_order_update_id_[vehicle_id]++;
3539	  const auto& catalog = catalog_reloader_->catalog();
3540	
3541	  const auto order = amr_dispatcher_core::fleet::BuildVda5050OrderFromPath(
3542	      vehicle_id, mission_id, update_id, path_it->second, catalog, held_locks);
3543	  if (!order.has_value()) {
3544	    RCLCPP_WARN(get_logger(),
3545	                "Mission %s -> vehicle %s: BuildVda5050OrderFromPath failed "
3546	                "(path %zu node(s)), VDA 5050 order NOT published",
3547	                mission_id.c_str(), vehicle_id.c_str(), path_it->second.size());
3548	    return;
3549	  }
3550	  const auto pub_it = vda5050_order_pubs_.find(vehicle_id);
3551	  if (pub_it == vda5050_order_pubs_.end() || !pub_it->second ||
3552	      !pub_it->second->is_activated()) {
3553	    RCLCPP_WARN(get_logger(),
3554	                "Mission %s -> vehicle %s: send_order publisher missing/inactive, "
3555	                "VDA 5050 order NOT published",
3556	                mission_id.c_str(), vehicle_id.c_str());
3557	    return;
3558	  }
3559	  std_msgs::msg::String out;
3560	  out.data = amr_dispatcher_core::fleet::SerializeVda5050Order(*order);
3561	  pub_it->second->publish(out);
3562	  // 登记 mission -> 车辆绑定：人工强清离线链路时据此反查"该车名下"的锁归属
3563	  vda5050_mission_vehicle_[mission_id] = vehicle_id;
3564	  RCLCPP_INFO(get_logger(),
3565	              "VDA 5050 order published: mission %s -> /fleet/%s/send_order "
3566	              "(orderId=%s, orderUpdateId=%u, %zu nodes, %zu edges, %zu bytes)",
3567	              mission_id.c_str(), vehicle_id.c_str(), order->order_id.c_str(),
3568	              update_id, order->nodes.size(), order->edges.size(), out.data.size());
3569	}
