3571	void DispatcherNode::Vda5050StateCb(const std::string& vehicle_id,
3572	                                    const std_msgs::msg::String::SharedPtr msg) {
3573	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(msg->data);
3574	  if (!report.has_value()) {
3575	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3576	                         "Malformed VDA 5050 state JSON from vehicle %s: %.128s",
3577	                         vehicle_id.c_str(), msg->data.c_str());
3578	    return;
3579	  }
3580	  // M1：状态报文必须与订阅话题的车辆身份一致，防止车 B 冒用车 A 的 orderId
3581	  // 驱动任务 A 的解锁流程。
3582	  if (report->vehicle_id != vehicle_id) {
3583	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3584	                         "VDA 5050 state identity mismatch: topic vehicle %s but "
3585	                         "serialNumber %s — dropped",
3586	                         vehicle_id.c_str(), report->vehicle_id.c_str());
3587	    return;
3588	  }
3589	  auto link_it = vda5050_link_states_.find(vehicle_id);
3590	  if (link_it != vda5050_link_states_.end()) {
3591	    // 选车输入：最近一帧的定位与电量（位置不可用 -> 该车不合格）。
3592	    // 迁移规则在 core（ApplyStateObservation）：数据照常更新，但**不改 online**。
3593	    amr_dispatcher_core::fleet::Vda5050StateObservation observation;
3594	    observation.position_initialized = report->agv_position_initialized;
3595	    observation.x = report->x;
3596	    observation.y = report->y;
3597	    observation.battery_percent = report->battery_percent;
3598	    const auto applied = amr_dispatcher_core::fleet::ApplyStateObservation(
3599	        &link_it->second, observation, std::chrono::steady_clock::now());
3600	    if (applied == amr_dispatcher_core::fleet::LinkStateApplyAction::kUpdatedWhileOffline) {
3601	      // 离线期间收到 state 绝不可回置 online=true：DDS 跨话题乱序可能把断链前
3602	      // 的最后一帧 state 排在 online=false 之后送达，若据此回置，链路会"永久
3603	      // 在线"并绕过 Spec §5.2 的调度挂起（e2e Stage 6.4 曾复现）。
3604	      // 链路存活的唯一权威判据是网关在 MQTT 有序流中确认断链之后、收到重连
3605	      // 后的新 state 或 connection=ONLINE 时重发的 online=true（网关侧见
3606	      // vda5050_gateway_node HandleState/HandleConnection）。此处仅告警：
3607	      // 锁保留、调度挂起状态均不改变；锁的解除仍由下方 Rule 1 的 lastNodeId
3608	      // 与订单一致性校验接管（不一致则全保留，Spec §5.2 位置重核对）。
3609	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3610	                           "VDA 5050 vehicle %s: state received while offline (locks "
3611	                           "retained, dispatch suspended) — awaiting gateway online=true "
3612	                           "re-publication after reconnect (Spec 5.2)",
3613	                           vehicle_id.c_str());
3614	    }
3615	  }
3616	  if (report->order_id.empty()) {
3617	    return;  // 无在途订单的 state（心跳/空订单）：不参与任务闭环
3618	  }
3619	  // 订单 -> 在途任务：网关订单 order_id = mission_id（BuildVda5050OrderFromPath），
3620	  // 兼容按 Mission.order_id 业务号匹配
3621	  auto mission_it = active_missions_.find(report->order_id);
3622	  if (mission_it == active_missions_.end()) {
3623	    for (auto it = active_missions_.begin(); it != active_missions_.end(); ++it) {
3624	      if (it->second.order_id == report->order_id) {
3625	        mission_it = it;
3626	        break;
3627	      }
3628	    }
3629	  }
3630	  if (mission_it == active_missions_.end()) {
3631	    return;  // 非本调度器在途任务的 state（重复/迟到/他人单）：幂等忽略，不碰锁
3632	  }
3633	  // 进度心跳：state 到达即刷新（VDA 5050 车不走 /tracking/error，
3634	  // 若不喂 progress，长距离巡航会被死锁检测判为 idle 并取消任务）。
3635	  mission_last_progress_[mission_it->first] = std::chrono::steady_clock::now();
3636	  const auto path_it = mission_route_paths_.find(mission_it->first);
3637	  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
3638	    return;  // 该单无行驶路径存档（无 pickup 等）：不参与动态解锁
3639	  }
3640	  if (!reservation_table_) {
3641	    return;  // 预约表不可用：不解锁、不判完成
3642	  }
3643	  // Rule 1（Spec §5.3）：按确认位置回推身后锁，仅释放本任务持有且已整段越过的部分
3644	  std::unordered_map<std::string, std::string> held_locks;
3645	  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
3646	    held_locks[resource_id] = owner;
3647	  }
3648	  const auto decision = amr_dispatcher_core::workflow::PlanTrailingUnlock(
3649	      path_it->second, report->last_node_id, report->last_node_sequence_id,
3650	      mission_it->first, held_locks);
3651	  if (!decision.confirmed) {
3652	    RCLCPP_WARN(get_logger(), "Dynamic unlock skipped (vehicle %s, order %s): %s",
3653	                vehicle_id.c_str(), report->order_id.c_str(), decision.message.c_str());
3654	    return;
3655	  }
3656	  // 更新该车最近一次确认到达的安全节点（供 Phase 7 交通协调与在途重规划锚定起点）
3657	  if (!report->last_node_id.empty()) {
3658	    vehicle_safe_nodes_[vehicle_id] = report->last_node_id;
3659	  }
3660	  if (!decision.lock_ids_to_release.empty()) {
3661	    const auto released = reservation_table_->ReleaseResources(mission_it->first,
3662	                                                               decision.lock_ids_to_release);
3663	    if (!released.empty()) {
3664	      std::string joined;
3665	      for (const auto& lock_id : released) {
3666	        if (!joined.empty()) joined += ",";
3667	        joined += lock_id;
3668	      }
3669	      RCLCPP_INFO(get_logger(),
3670	                  "Dynamic unlock (Spec 5.3): vehicle %s at %s -> mission %s released %zu lock(s): %s",
3671	                  vehicle_id.c_str(), report->last_node_id.c_str(), mission_it->first.c_str(),
3672	                  released.size(), joined.c_str());
3673	      // B2：窗口到期 != 资源已释放——车辆**确认驶离**该资源后才释放其时间窗，
3674	      // 否则后车会在前车还在时进入。
3675	      if (UseTimeSpaceMode()) {
3676	        ReleaseTimeSpaceForResources(mission_it->first, released);
3677	      }
3678	      if (event_log_) {
3679	        amr_dispatcher_core::dispatcher::MissionEvent evt;
3680	        evt.stamp = "now";
3681	        evt.mission_id = mission_it->first;
3682	        evt.event = "dynamic_unlock";
3683	        evt.message = "vehicle " + vehicle_id + " at " + report->last_node_id + " released " + joined;
3684	        event_log_->Append(evt);
3685	      }
3686	      ReArmQueueStartRequest();  // 唤醒排队等待这批锁的后车重试派发
3687	    }
3688	  }
3689	
3690	  // ---- VDA 5050 完成判定（评审 P0.1）----
3691	  // 外部标准协议车自带控制器，**没有** /plan 也没有 /tracking/error：
3692	  // "任务完成" = state 报文的 lastNodeId 推进到订单终点。
3693	  // 若仍用 /tracking/error 的 arrived 判完成，多车场景会张冠李戴。
3694	  // 判定放在逐段解锁**之后**：到达终点的那一帧同时要释放身后的锁（Spec §5.3）。
3695	  if (report->last_node_id != path_it->second.back()) {
3696	    return;  // 未到终点：继续在途
3697	  }
3698	  const auto bind_it = vda5050_mission_vehicle_.find(mission_it->first);
3699	  if (bind_it != vda5050_mission_vehicle_.end() && bind_it->second != vehicle_id) {
3700	    return;  // 该单绑定的是别的车：不误判完成
3701	  }
3702	  RCLCPP_INFO(get_logger(),
3703	              "VDA 5050 vehicle %s reached final node %s -> completing mission %s",
3704	              vehicle_id.c_str(), report->last_node_id.c_str(), mission_it->first.c_str());
3705	  // 原因串保持 "arrived at goal" —— 完成日志是既有可观测契约（e2e 断言依赖）。
3706	  CompleteMission(mission_it->first, "arrived at goal");
3707	}
