3709	void DispatcherNode::Vda5050OnlineCb(const std::string& vehicle_id,
3710	                                     const std_msgs::msg::Bool::SharedPtr msg) {
3711	  auto it = vda5050_link_states_.find(vehicle_id);
3712	  if (it == vda5050_link_states_.end()) {
3713	    return;
3714	  }
3715	  // 状态未变（transient_local 重放/重复报文）不重复告警——翻转判定在 core
3716	  if (!amr_dispatcher_core::fleet::ApplyOnlineReport(&it->second, msg->data)) {
3717	    return;
3718	  }
3719	  if (!msg->data) {
3720	    // Rule 2（Spec §5.2 断链锁定保护）：仅标记离线 + 软看门狗告警，绝不释放任何锁。
3721	    // 锁保留直至该车重连后 state 重核对坐标，或操作员人工强制解除。
3722	    const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
3723	        /*vehicle_online=*/false, /*state_stale=*/false);
3724	    RCLCPP_WARN(get_logger(), "VDA 5050 vehicle %s link broken: %s", vehicle_id.c_str(),
3725	                guard.message.c_str());
3726	    if (event_log_) {
3727	      amr_dispatcher_core::dispatcher::MissionEvent evt;
3728	      evt.stamp = "now";
3729	      evt.mission_id = "-";  // 无任务级事件：链路级看门狗告警
3730	      evt.event = "vehicle_offline";
3731	      evt.message = "vehicle " + vehicle_id + ": retaining all route locks pending "
3732	                    "reconnection and position re-verification (Spec 5.2)";
3733	      event_log_->Append(evt);
3734	    }
3735	  } else {
3736	    RCLCPP_INFO(get_logger(),
3737	                "VDA 5050 vehicle %s back online: locks retained until state re-confirms "
3738	                "lastNodeId against the order (Spec 5.2 position re-verification)",
3739	                vehicle_id.c_str());
3740	  }
3741	}
