3743	bool DispatcherNode::EnforceVda5050LinkGuard() {
3744	  if (vda5050_link_states_.empty()) {
3745	    return false;  // 未配置受管小车：关闭状态，零开销
3746	  }
3747	  // 判定下沉 core 纯函数（隔离车跳过 / 任一离线车阻断 / stale 只告警），
3748	  // ROS 侧只做"采集 + 按判定打日志"。铁律 retain_all_locks 恒真。
3749	  amr_dispatcher_core::workflow::FleetLinkGuardRequest request;
3750	  request.state_stale_sec = vda5050_state_stale_sec_;
3751	  const auto now = std::chrono::steady_clock::now();
3752	  for (const auto& [vehicle_id, link] : vda5050_link_states_) {
3753	    amr_dispatcher_core::workflow::VehicleLinkInput input;
3754	    input.vehicle_id = vehicle_id;
3755	    input.online = link.online;
3756	    input.quarantined = link.quarantined;
3757	    input.seen_state = link.seen_state;
3758	    if (link.seen_state) {
3759	      input.state_age_sec =
3760	          std::chrono::duration_cast<std::chrono::milliseconds>(now - link.last_state_time)
3761	              .count() /
3762	          1000.0;
3763	    }
3764	    request.vehicles.push_back(std::move(input));
3765	  }
3766	  const auto decision =
3767	      amr_dispatcher_core::workflow::EvaluateFleetLinkGuard(request);
3768	  for (const auto& verdict : decision.verdicts) {
3769	    switch (verdict.kind) {
3770	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kSuspendDispatch:
3771	        // 日志文案逐字保留（e2e 直接 grep "Dispatch suspended:"）
3772	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3773	                             "Dispatch suspended: %s (vehicle %s). On recovery the vehicle's "
3774	                             "position is re-verified via state before any lock is released.",
3775	                             verdict.message.c_str(), verdict.vehicle_id.c_str());
3776	        break;
3777	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kStaleWarning:
3778	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000, "VDA 5050 vehicle %s: %s",
3779	                             verdict.vehicle_id.c_str(), verdict.message.c_str());
3780	        break;
3781	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kSkip:
3782	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kHealthy:
3783	        break;
3784	    }
3785	  }
3786	  return decision.block_new_dispatch;
3787	}
