3811	amr_dispatcher_core::dispatcher::DispatchStateSnapshot DispatcherNode::BuildStateSnapshot() {
3812	  amr_dispatcher_core::dispatcher::DispatchStateSnapshot snapshot;
3813	  snapshot.map_hash = catalog_reloader_ ? catalog_reloader_->catalog().map_hash : std::string();
3814	  snapshot.next_sequence = next_sequence_;
3815	  if (queue_) {
3816	    snapshot.queued_missions = queue_->SnapshotForPersistence();
3817	    for (const auto& m : snapshot.queued_missions) {
3818	      if (!m.order_id.empty() && queue_->IsOrderPaused(m.order_id) &&
3819	          std::find(snapshot.paused_order_ids.begin(), snapshot.paused_order_ids.end(),
3820	                    m.order_id) == snapshot.paused_order_ids.end()) {
3821	        snapshot.paused_order_ids.push_back(m.order_id);
3822	      }
3823	    }
3824	  }
3825	  {
3826	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
3827	    for (const auto& [id, mission] : active_missions_) {
3828	      snapshot.active_missions.push_back(mission);
3829	    }
3830	  }
3831	  for (const auto& [vid, link_state] : vda5050_link_states_) {
3832	    if (link_state.quarantined) {
3833	      snapshot.quarantined_vehicle_ids.push_back(vid);
3834	    }
3835	  }
3836	  return snapshot;
3837	}
