3839	void DispatcherNode::FlushStateSnapshot() {
3840	  if (state_snapshot_file_.empty()) {
3841	    return;
3842	  }
3843	  const auto snapshot = BuildStateSnapshot();
3844	  std::string message;
3845	  if (amr_dispatcher_core::dispatcher::WriteDispatchStateAtomic(state_snapshot_file_, snapshot,
3846	                                                               &message)) {
3847	    ++state_snapshot_writes_;
3848	    state_snapshot_dirty_ = false;
3849	    last_state_snapshot_error_.clear();
3850	    return;
